let anSub='stock';
function activeTab(){const a=document.querySelector('.tab-content.active');return a?a.id.replace('tab-',''):''}
function switchTab(tab){if(tab==='forecast'||tab==='inventory'){anSub=tab==='forecast'?'forecast':'stock';tab='analysis'}
document.querySelectorAll('.tab-content').forEach(t=>t.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));document.getElementById('tab-'+tab).classList.add('active');const ni=document.querySelector(`.nav-item[data-tab="${tab}"]`);if(ni)ni.classList.add('active');
if(tab==='analysis')setSub(anSub);if(tab==='replenishment')loadReplenishment();if(tab==='po')loadPoPage();if(tab==='upload')loadDataStatus();
window.scrollTo(0,0);closeAllCdrops();if(tab==='overview')requestAnimationFrame(applyRiskLimit)}
function setSub(v){anSub=v;markSeg('anSeg',v);document.getElementById('sub-stock').classList.toggle('active',v==='stock');document.getElementById('sub-forecast').classList.toggle('active',v==='forecast');if(v==='forecast'){if(dpView==='weekly')loadWeekly();else loadPlan()}else loadInventory()}
function reloadActive(){const t=activeTab();if(t==='analysis'){if(anSub==='forecast'){if(dpView==='weekly')loadWeekly();else loadPlan()}else loadInventory()}if(t==='replenishment')loadReplenishment()}
function sparklineSvg(d,w=80,h=22,color='var(--chart-2)'){if(!d||d.length<2)return'';const mx=Math.max(...d,1);const pts=d.map((v,i)=>`${((i/(d.length-1))*w).toFixed(1)},${(h-1-(v/mx)*(h-2)).toFixed(1)}`).join(' ');return`<svg class="sparkline" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><polyline points="${pts}" fill="none" style="stroke:${color}" stroke-width="1.5" stroke-linejoin="round"/></svg>`}
function trendBadge(t){return t==='up'?'<span class="trend-up" title="Rising">&#9650;</span>':t==='down'?'<span class="trend-down" title="Falling">&#9660;</span>':'<span class="trend-stable" title="Stable">&#9654;</span>'}
function statusBadge(s){if(s==null)return'<span class="badge badge-gray" title="No sales in 4 weeks and no stock: not one of the 3 statuses">Not classified</span>';const m={understocked:'badge-red',healthy:'badge-green',overstocked:'badge-slate'};const l={understocked:'Understocked',healthy:'Healthy',overstocked:'Overstocked'};return`<span class="badge ${m[s]||'badge-gray'}">${l[s]||s}</span>`}
function urgBadge(u){if(!u)return'<span class="text-dim">--</span>';return`<span class="urg urg-${u}">${u}</span>`}
const MOVE_L={fast:'Fast',medium:'Medium',slow:'Slow',non_moving:'Non-moving'};
function moveBadge(m){const c={fast:'badge-green',medium:'badge-blue',slow:'badge-yellow',non_moving:'badge-gray'}[m]||'badge-gray';return`<span class="badge ${c}">${MOVE_L[m]||'--'}</span>`}
const fmtRpS=n=>{if(n==null)return'--';const a=Math.abs(n);return a>=1e9?'Rp '+(n/1e9).toFixed(2).replace('.',',')+' M':a>=1e6?'Rp '+(n/1e6).toFixed(1).replace('.',',')+' jt':fmtRp(n)};
function costTag(verified){return verified?'':' <span class="tag tag-warn" title="Unit cost from cogs_accurate, not yet confirmed by finance as HPP">Unverified</span>'}
function trendClassBadge(c,p){const m={increasing:['trend-up','▲','Increasing'],decreasing:['trend-down','▼','Decreasing'],stable:['trend-stable','▶','Stable'],new_demand:['trend-up','★','New demand'],insufficient_baseline:['text-dim','–','No baseline']}[c];if(!m)return'<span class="text-dim">--</span>';return`<span class="${m[0]}" title="${m[2]}${p!=null?' ('+(p>0?'+':'')+p+'% vs last 8 weeks)':''}">${m[1]} ${p!=null?(p>0?'+':'')+p+'%':m[2]}</span>`}
const MON_S=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const dfmt=iso=>{if(!iso)return'--';const d=new Date(iso+'T00:00:00');return`${d.getDate()} ${MON_S[d.getMonth()]} ${d.getFullYear()}`};
function info(tip){return`<span class="info" tabindex="0" role="button" aria-label="More info" data-tip="${esc(tip)}">i</span>`}
function renderFresh(f){const els=document.querySelectorAll('.fresh-banner,#ovFresh');let html='',tip='',cls='warn';
if(f&&!f.stock_date){cls='crit';html='<b>No stock snapshot yet</b>';tip='Upload a stock report on the Upload Data page — stock, coverage and recommendations need it.'}
else if(f&&(f.stock_level==='stale'||f.stock_level==='very_stale')){cls=f.stock_level==='very_stale'?'crit':'warn';html=`<b>Stock data is ${f.stock_age_days} days old</b> · snapshot ${dfmt(f.stock_date)}`;tip=`Stock on hand is not real-time.${f.stock_level==='very_stale'?' Upload a new stock report before acting on purchase recommendations.':''}${f.last_sale_date?` Latest sales: ${dfmt(f.last_sale_date)} (${f.sales_age_days} days ago).`:''}`}
els.forEach(e=>{if(!html){e.hidden=true;return}e.hidden=false;e.className=(e.id==='ovFresh'?'fresh-line ':'fresh-line fresh-banner ')+cls;e.innerHTML=ICON.alert.replace('<svg','<svg class="b-ico"')+'<span>'+html+'</span>'+info(tip)})}
/* hover / focus / tap tooltips for every .info icon */
(function(){const box=()=>document.getElementById('tipBox');let cur=null;
function show(el){const t=el.getAttribute('data-tip');if(!t)return;const b=box();if(!b)return;cur=el;document.querySelectorAll('.info.on').forEach(x=>x.classList.remove('on'));el.classList.add('on');b.textContent=t;b.classList.add('show');const r=el.getBoundingClientRect(),bw=b.offsetWidth,bh=b.offsetHeight;let x=r.left+r.width/2-bw/2;x=Math.max(10,Math.min(x,innerWidth-bw-10));let y=r.bottom+8;if(y+bh>innerHeight-10)y=r.top-bh-8;b.style.left=x+'px';b.style.top=Math.max(10,y)+'px'}
function hide(){const b=box();if(b)b.classList.remove('show');if(cur)cur.classList.remove('on');cur=null}
document.addEventListener('mouseover',e=>{const el=e.target.closest&&e.target.closest('.info');if(el)show(el)});
document.addEventListener('mouseout',e=>{const el=e.target.closest&&e.target.closest('.info');if(el&&!el.contains(e.relatedTarget))hide()});
document.addEventListener('focusin',e=>{if(e.target.classList&&e.target.classList.contains('info'))show(e.target)});
document.addEventListener('focusout',e=>{if(e.target.classList&&e.target.classList.contains('info'))hide()});
document.addEventListener('click',e=>{const el=e.target.closest&&e.target.closest('.info');if(el){e.stopPropagation();if(cur===el)hide();else show(el)}else hide()},true);
addEventListener('scroll',hide,true);addEventListener('resize',hide)})();
function renderPaging(id,pg,total,fn,label='products',size=PAGE_SIZE){const pages=Math.ceil(total/size);if(pages<=1){document.getElementById(id).innerHTML=`<span>${total} ${label}</span>`;return}document.getElementById(id).innerHTML=`<button onclick="${fn}(${pg-1})" ${pg===0?'disabled':''}>&#8249;</button><span class="current">${pg+1}</span>/${pages}<button onclick="${fn}(${pg+1})" ${pg>=pages-1?'disabled':''}>&#8250;</button> <span>${total} ${label}</span>`}

/* Ring gauge */
function ringSvg(pct,color,size=76,stroke=8){const r=(size-stroke)/2,c=2*Math.PI*r,p=Math.max(0,Math.min(100,pct||0));return`<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" style="stroke:var(--seg)" stroke-width="${stroke}"/><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" style="stroke:${color}" stroke-width="${stroke}" stroke-linecap="round" stroke-dasharray="${(c*p/100).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 ${size/2} ${size/2})"/><text x="50%" y="50%" text-anchor="middle" dominant-baseline="central" style="fill:var(--text);font:700 17px Inter,sans-serif">${pct==null?'--':Math.round(p)}</text></svg>`}
/* Concentric rings */
function concentricSvg(items,total,size=172){const stroke=9,gap=5;let s=`<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">`;items.forEach((it,i)=>{const r=size/2-stroke/2-i*(stroke+gap);const c=2*Math.PI*r;const f=total?it.v/total:0;s+=`<circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" style="stroke:var(--seg)" stroke-width="${stroke}"/>`;if(f>0)s+=`<circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" style="stroke:${it.color}" stroke-width="${stroke}" stroke-linecap="round" stroke-dasharray="${Math.max(c*f,0.1).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 ${size/2} ${size/2})"/>`});s+=`<text x="50%" y="47%" text-anchor="middle" dominant-baseline="central" style="fill:var(--text);font:700 22px Inter,sans-serif">${fmt(total)}</text><text x="50%" y="60%" text-anchor="middle" dominant-baseline="central" style="fill:var(--text3);font:500 11px Inter,sans-serif">SKUs</text></svg>`;return s}

/* ═══ DROPDOWN ═══ */
function cDropVal(id){const el=document.querySelector(`.cdrop[data-id="${id}"] .cdrop-opt.active`);return el?el.dataset.val:''}
function toggleCdrop(btn){const menu=btn.nextElementSibling;const isOpen=menu.classList.contains('show');closeAllCdrops();if(!isOpen){menu.classList.add('show');btn.classList.add('open')}}
function selectCdrop(opt){const menu=opt.parentElement;const cdrop=menu.parentElement;const id=cdrop.dataset.id;menu.querySelectorAll('.cdrop-opt').forEach(o=>o.classList.remove('active'));opt.classList.add('active');cdrop.querySelector('.cdrop-label').textContent=opt.textContent.trim();menu.classList.remove('show');cdrop.querySelector('.cdrop-btn').classList.remove('open');const actions={topSortSelect:changeTopSort,weeklyTrend:filterWeekly,invStatus:filterInv,invSort:loadInventory,invMove:filterInv};if(actions[id])actions[id]()}
function closeAllCdrops(){document.querySelectorAll('.cdrop-menu.show').forEach(m=>{m.classList.remove('show');m.previousElementSibling.classList.remove('open')})}
document.addEventListener('click',e=>{if(!e.target.closest('.cdrop'))closeAllCdrops();if(!e.target.closest('#customRange')&&!e.target.closest('.pill[data-p="custom"]'))document.getElementById('customRange').classList.remove('show');if(!e.target.closest('#monthGrid')&&!e.target.closest('#pillMonth'))document.getElementById('monthGrid').classList.remove('show')});

