function getCT(){return{grid:cv('--grid'),tick:cv('--text3'),font:{size:12,family:'Inter'},tipBg:cv('--surface'),tipTitle:cv('--text'),tipBody:cv('--text2'),tipBorder:cv('--border2')}}
function baseOpts(yCb,labelCb){const ct=getCT();return{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{backgroundColor:ct.tipBg,titleColor:ct.tipTitle,bodyColor:ct.tipBody,borderColor:ct.tipBorder,borderWidth:1,padding:10,cornerRadius:8,callbacks:labelCb?{label:labelCb}:{}}},scales:{x:{grid:{display:false},border:{color:ct.grid},ticks:{color:ct.tick,font:ct.font,maxRotation:0,autoSkipPadding:12}},y:{grid:{color:ct.grid},border:{display:false},min:0,ticks:{color:ct.tick,font:ct.font,callback:yCb}}}}}
function areaFill(ctx,hex){const g=ctx.createLinearGradient(0,0,0,ctx.canvas.clientHeight||220);g.addColorStop(0,hexA(hex,.18));g.addColorStop(1,hexA(hex,0));return g}

