let ovSeq=0,lastOv=null,lastRisk=[];
let riskSeq=0;
function loadRiskOnly(){const seq=++riskSeq,rt=PT;return fetch(`/api/best-sellers-at-risk?product_type=${rt}`).then(r=>r.ok?r.json():{results:[]}).then(risk=>{if(seq!==riskSeq)return;lastRisk=risk.results||[];riskInfo=risk;updateRiskMeta();renderRisk(lastRisk,rt);refreshInsights()}).catch(()=>{})}
function refreshInsights(){if(lastOv)renderInsights(lastOv,lastRisk,invSummaryCache)}
async function loadOverview(){const seq=++ovSeq;if(!scopeData)loadScope();try{const ts=cDropVal('topSortSelect')||'revenue',tt=PT;let url;const s=document.getElementById('dateStart').value,e=document.getElementById('dateEnd').value;if(currentPreset==='custom'&&s&&e){url=`/api/overview?start=${s}&end=${e}&top_sort=${ts}&product_type=${tt}`}else{url=`/api/overview?preset=${currentPreset==='custom'?'l4w':currentPreset}&top_sort=${ts}&product_type=${tt}`}
// Slow/secondary requests start now but nothing waits for them.
loadRiskOnly();
fetch('/api/db/stats').then(r=>r.ok?r.json():null).then(stats=>{if(!stats||seq!==ovSeq)return;document.getElementById('lastUpdate').textContent=stats.last_update||'--';document.getElementById('dbInfo').innerHTML=`Connected · <strong>${fmt(stats.sales)}</strong> sales · <strong>${fmt(stats.products)}</strong> products · <strong>${stats.date_range||'--'}</strong>`}).catch(()=>{});
const oR=await fetch(url);if(!oR.ok)throw new Error('Overview request failed ('+oR.status+')');const ov=await oR.json();if(seq!==ovSeq)return;lastOv=ov;
const p=ov.period||{},pp=ov.prev_period||{};
document.getElementById('periodInfo').innerHTML=p.start?`${{import:'Import products',food:'Food products',all:'All products'}[PT]} · <b>${p.start} – ${p.end}</b> (${p.days} days), compared with ${pp.start} – ${pp.end}`:'Business overview';
const k=ov.kpis||{},cmp=ov.comparison||{};
countUp('kpiSales',k.total_sales||0,fmt);countUp('kpiRevenue',k.revenue||0,fmtRp);countUp('kpiAvgWeekly',k.avg_weekly_sales||0,fmt);countUp('kpiActive',k.active_products||0,fmt);countUp('kpiTrending',k.trending_up||0,fmt);
setCmp('cmpSales',cmp.total_sales);setCmp('cmpRevenue',cmp.revenue);setCmp('cmpAvgWeekly',cmp.avg_weekly_sales);setCmp('cmpActive',cmp.active_products);
const aggTxt=p.aggregation==='day'?'per day':'per period';
document.getElementById('chRevMeta').textContent=`Rupiah, ${aggTxt}`;document.getElementById('chSalesMeta').textContent=`Units sold, ${aggTxt}`;
const trend=ov.trend||[];lastTrend=trend.length?trend:null;lastAgg=p.aggregation;if(lastTrend){renderRevChart(trend,p.aggregation);renderSalesChart(trend,p.aggregation)}
if((ov.top_products||[]).length)renderTopTable(ov.top_products);
const fcs=ov.forecast_summary;['fcsDemand8w','fcsTotal','fcsMape','fcsTrendDown','ringAccVal'].forEach(i=>document.getElementById(i).classList.remove('skel'));if(fcs){document.getElementById('fcsDemand8w').textContent=fmt(fcs.forecast_demand_8w);document.getElementById('fcsTotal').textContent=fmt(fcs.total_forecasted);document.getElementById('fcsMape').textContent=fcs.avg_mape!=null?fcs.avg_mape+'%':'--';document.getElementById('fcsTrendDown').textContent=fmt(fcs.trending_down)}
renderRings(fcs,invSummaryCache);refreshInsights();
fetchInvSummary().then(inv=>{if(seq!==ovSeq)return;document.getElementById('ringHealthVal').classList.remove('skel');renderRings(ov.forecast_summary,inv);refreshInsights()});
const projPT=PT;document.getElementById('projMeta').textContent='Weekly units, '+(PT==='all'?'all':PT)+' SKUs';fetchWeekly(PT,'bestseller').then(d=>{if(projPT===PT)renderProjection(d.results)}).catch(()=>renderProjection([]));
}catch(e){document.getElementById('dbInfo').innerHTML='Error · '+esc(e.message)}}

function setCmp(id,v){const el=document.getElementById(id);if(!el)return;if(v==null){el.textContent='';el.className='kpi-cmp';return}el.className='kpi-cmp '+(v>0?'up':v<0?'down':'');el.textContent=`${v>0?'↑':v<0?'↓':'→'} ${Math.abs(v)}% vs previous`}

function renderRings(fcs,inv){const hw=fcs&&fcs.holdout_wmape!=null;const acc=hw?Math.max(0,100-fcs.holdout_wmape):(fcs&&fcs.avg_mape!=null?Math.max(0,100-fcs.avg_mape):null);document.getElementById('ringAcc').innerHTML=ringSvg(acc,'var(--chart-1)');document.getElementById('ringAccVal').textContent=acc!=null?acc.toFixed(1)+'%':'--';document.getElementById('ringAccSub').textContent=hw?`100 − WMAPE, out-of-sample (last 8 weeks, ${fcs.holdout_evaluated} SKUs)`:'100 − avg MAPE, in-sample · run Refresh forecast for holdout WMAPE';
let health=null,tot=0;if(inv){tot=(inv.understocked||0)+(inv.healthy||0)+(inv.overstocked||0);if(tot)health=(inv.healthy||0)/tot*100}
document.getElementById('ringHealth').innerHTML=ringSvg(health,'var(--chart-2)');document.getElementById('ringHealthVal').textContent=health!=null?health.toFixed(1)+'%':'--';document.getElementById('ringHealthSub').textContent=tot?`${fmt(inv.healthy||0)} of ${fmt(tot)} ${ptWord()}SKUs healthy`:'Share of '+ptWord()+'SKUs in healthy status'}

function renderInsights(ov,risk,inv){const out=[];const cmp=ov.comparison||{};
const fr=invOv&&invOv.freshness;if(fr&&(fr.stock_level==='stale'||fr.stock_level==='very_stale'))out.push({c:'var(--amber)',h:`Stock snapshot is <b>${fr.stock_age_days} days old</b> — upload a new stock report before ordering.`,a:'upload'});
if(invOv&&invOv.order_overdue)out.push({c:'var(--red)',h:`<b>${fmt(invOv.order_overdue)} best sellers</b> are past their order date — an order placed today arrives after the projected stockout.`,a:'replenishment'});else if(invOv&&invOv.order_soon)out.push({c:'var(--amber)',h:`<b>${fmt(invOv.order_soon)} best sellers</b> must be ordered within 14 days.`,a:'replenishment'});
if(inv&&inv.needs_po_check)out.push({c:'var(--amber)',h:`<b>${fmt(inv.needs_po_check)} SKUs</b> have open POs without an ETA — confirm them before reordering.`,a:'po'});
if(risk.length){const n=riskInfo.total_understocked||risk.length;const w=risk.filter(r=>r.coverage!=null).sort((a,b)=>a.coverage-b.coverage)[0];out.push({c:'var(--red)',h:`<b>${n} best seller${n>1?'s':''}</b> at risk of stockout${w?` — lowest coverage: <b>${w.sku}</b> (${w.coverage.toFixed(1)} weeks)`:''}.`,a:'inventory'})}
if(inv&&(inv.understocked||0)>0)out.push({c:'var(--red)',h:`<b>${fmt(inv.understocked)} ${ptWord()}SKUs</b> are understocked (less than 8 weeks of stock).`,a:'inventory'});
if(cmp.revenue!=null)out.push({c:cmp.revenue>=0?'var(--green)':'var(--red)',h:`Revenue ${cmp.revenue>=0?'up':'down'} <b>${Math.abs(cmp.revenue)}%</b> vs the previous period.`});
const f=ov.forecast_summary;if(f&&f.avg_mape!=null)out.push({c:'var(--blue)',h:`${f.holdout_wmape!=null?`Out-of-sample WMAPE is <b>${f.holdout_wmape}%</b> (in-sample MAPE ${f.avg_mape}%)`:`Average in-sample MAPE is <b>${f.avg_mape}%</b>`}${f.trending_down?`; <b>${fmt(f.trending_down)} SKUs</b> forecast &gt;10% below the last 8 weeks`:''}.`,a:'forecast'});
if(!out.length)out.push({c:'var(--slate)',h:'No notable signals for this period.'});
document.getElementById('insightList').innerHTML=out.map(i=>`<li><span class="ins-dot" style="background:${i.c}"></span><span>${i.h}</span>${i.a?`<button class="link-btn" onclick="switchTab('${i.a}')">View</button>`:''}</li>`).join('')}

function renderRevChart(data,agg){const ctx=document.getElementById('revChart').getContext('2d');if(revChartObj)revChartObj.destroy();const labels=data.map(d=>agg==='day'?d.date.substring(5):d.date.substring(0,7));const c1=cv('--chart-1');revChartObj=new Chart(ctx,{type:'line',data:{labels,datasets:[{data:data.map(d=>d.revenue),borderColor:c1,backgroundColor:areaFill(ctx,c1),fill:true,tension:.35,pointRadius:0,pointHoverRadius:4,pointBackgroundColor:c1,borderWidth:2}]},options:baseOpts(v=>'Rp'+(v/1e6).toFixed(0)+'M',c=>fmtRp(c.parsed.y))})}
function renderSalesChart(data,agg){const ctx=document.getElementById('salesChart').getContext('2d');if(salesChartObj)salesChartObj.destroy();const labels=data.map(d=>agg==='day'?d.date.substring(5):d.date.substring(0,7));const c4=cv('--chart-4');salesChartObj=new Chart(ctx,{type:'line',data:{labels,datasets:[{data:data.map(d=>d.quantity),borderColor:c4,backgroundColor:areaFill(ctx,c4),fill:true,tension:.35,pointRadius:0,pointHoverRadius:4,pointBackgroundColor:c4,borderWidth:2}]},options:baseOpts(v=>fmt(v),c=>fmt(c.parsed.y)+' units')})}

/* Actual vs Forecast (aggregated) */
function renderProjection(rows){const spark=(rows||[]).map(r=>r.sparkline||[]).filter(a=>a.length);const n=spark.length?Math.max(...spark.map(a=>a.length)):0;const actual=Array(n).fill(0);spark.forEach(a=>{const off=n-a.length;a.forEach((v,i)=>actual[off+i]+=Number(v)||0)});
const inSet=new Set((rows||[]).map(r=>r.sku));const fq=Object.values(fcDataMap).filter(f=>inSet.has(f.sku)).map(f=>(f.forecast_data&&f.forecast_data.quantities)||[]).filter(a=>a.length);const m=fq.length?Math.max(...fq.map(a=>a.length)):0;const forecast=Array(m).fill(0);fq.forEach(a=>a.forEach((v,i)=>forecast[i]+=Number(v)||0));
document.getElementById('fcsSpark').innerHTML=sparklineSvg(forecast.slice(0,8),90,28);
if(!n&&!m){lastProj=null;document.getElementById('projWrap').innerHTML='<div class="empty-state">No weekly data or forecast results yet.</div>';return}
lastProj={actual,forecast};renderProjChart()}
function renderProjChart(){if(!lastProj)return;let cvs=document.getElementById('projChart');if(!cvs){document.getElementById('projWrap').innerHTML='<canvas id="projChart"></canvas>';cvs=document.getElementById('projChart')}const ctx=cvs.getContext('2d');if(projChartObj)projChartObj.destroy();const{actual,forecast}=lastProj;const n=actual.length,m=forecast.length;
const labels=[...actual.map((_,i)=>`W-${n-i}`),...forecast.map((_,i)=>`W+${i+1}`)];
const aData=[...actual,...Array(m).fill(null)];const fData=n?[...Array(n-1).fill(null),actual[n-1],...forecast]:[...forecast];
const c1=cv('--chart-1'),c2=cv('--chart-2');
projChartObj=new Chart(ctx,{type:'line',data:{labels,datasets:[{label:'Actual',data:aData,borderColor:c1,backgroundColor:areaFill(ctx,c1),fill:true,tension:.3,pointRadius:0,pointHoverRadius:4,borderWidth:2,spanGaps:false},{label:'Forecast',data:fData,borderColor:c2,fill:false,borderDash:[6,4],tension:.3,pointRadius:0,pointHoverRadius:4,borderWidth:2,spanGaps:false}]},options:baseOpts(v=>fmt(v),c=>`${c.dataset.label}: ${fmt(Math.round(c.parsed.y))} units`)})}

function renderTopTable(data){let h='<thead><tr><th>SKU</th><th>Product</th><th class="r">Sales</th><th class="r">Revenue</th><th class="r">Growth</th></tr></thead><tbody>';data.forEach(r=>{let gt,gc='';if(r.is_new){gt='<span class="badge badge-blue">New</span>'}else if(r.growth!=null){gc=r.growth>0?'num-pos':r.growth<0?'num-neg':'';gt=fmtPct(r.growth)}else{gt='<span class="text-dim">No prev</span>'}h+=`<tr><td class="t-strong">${r.sku}</td><td class="t-strong" style="font-weight:500">${(r.name||'').substring(0,45)}</td><td class="r t-strong">${fmt(r.qty)}</td><td class="r">${fmtRp(r.revenue)}</td><td class="r ${gc}">${gt}</td></tr>`});h+='</tbody>';document.getElementById('topTable').innerHTML=h}
const LEAD_WEEKS=8,BAR_WEEKS=12;
function renderRisk(data,rt='all'){const sec=document.getElementById('riskSection');if(!data.length){if(rt==='all'){sec.style.display='none';return}sec.style.display='block';document.getElementById('riskGrid').innerHTML=`<div class="empty-state" style="grid-column:1/-1">No ${rt} best sellers at risk.</div>`;document.getElementById('riskMore').hidden=true;return}sec.style.display='block';
const rows=sortRisk(data).slice(0,10);
document.getElementById('riskGrid').innerHTML=rows.map(r=>{const cov=r.coverage;const col=cov==null?'var(--slate)':cov<8?'var(--red)':cov<=20?'var(--green)':'var(--slate)';const pct=cov==null?0:Math.min(100,cov/BAR_WEEKS*100);const name=esc(r.name||'');
return`<article class="risk-card"><div class="rc-top"><span class="rc-sku" title="${esc(r.sku)}">${esc(r.sku)}</span>${statusBadge(r.status)}</div>
<div class="rc-name" title="${name}">${name}</div>
<div class="rc-cov"><span class="rc-cov-v" style="color:${col}">${cov!=null?cov.toFixed(1):'--'}</span><span class="rc-cov-l">weeks of stock</span></div>
<div class="rc-bar" title="${cov!=null?cov.toFixed(1):'--'} of ${LEAD_WEEKS} weeks lead time"><span style="width:${pct}%;background:${col}"></span><i style="left:${LEAD_WEEKS/BAR_WEEKS*100}%"></i></div>
<div class="rc-meta"><div><div class="l">${riskInfo.comparison_available?'Stock '+riskWeeksAgo():'Stock now'}</div><div class="v" title="${riskInfo.comparison_available?'Stock then → now':'Only one stock snapshot: no comparison yet'}">${riskInfo.comparison_available&&r.prev_stock!=null?fmt(r.prev_stock)+' → '+fmt(r.current_stock):fmt(r.current_stock)}${riskInfo.comparison_available&&r.stock_change_pct!=null?` <span class="${r.stock_change_pct<0?'num-neg':'num-pos'}">(${r.stock_change_pct>0?'+':''}${r.stock_change_pct}%)</span>`:''}</div></div><div><div class="l">Order by</div><div class="v">${r.order_by?`<span class="${r.order_by_days<0?'num-neg':r.order_by_days<=14?'':'text-dim'}">${dfmt(r.order_by)}</span>`:'--'}</div></div><div><div class="l">L4W sales</div><div class="v">${fmt(r.l4w_qty)}</div></div><div><div class="l">Revenue L4W</div><div class="v" title="${fmtRp(r.revenue)}">${fmtRp(r.revenue)}</div></div></div>
<button class="btn btn-ghost rc-btn" onclick="reviewSku('${String(r.sku).replace(/'/g,"\\'")}')">Plan order</button></article>`}).join('');applyRiskLimit()}
let riskShowAll=false,riskMode='urgent',riskInfo={};
// Most urgent: purchase urgency (projected stockout vs lead time), then fewest weeks of stock,
// then the biggest stock drop vs ~8 weeks ago (only when a second snapshot exists), then revenue.
const URG_O={critical:0,high:1,medium:2,low:3};
function sortRisk(d){const a=[...d];if(riskMode==='revenue')return a.sort((x,y)=>(y.revenue||0)-(x.revenue||0));const ob=v=>v||'9999-12-31',cov=v=>v==null?1e9:v,chg=v=>v==null?1e9:v;return a.sort((x,y)=>ob(x.order_by).localeCompare(ob(y.order_by))||cov(x.coverage)-cov(y.coverage)||chg(x.stock_change_pct)-chg(y.stock_change_pct)||(y.revenue||0)-(x.revenue||0))}
function riskWeeksAgo(){return riskInfo.weeks_between?`(${Math.round(riskInfo.weeks_between)} wks ago → now)`:'now'}
function updateRiskMeta(){const el=document.getElementById('riskMeta');if(!el)return;const order=riskMode==='urgent'?'earliest order date first':'highest revenue first';el.innerHTML=`${riskInfo.total_understocked!=null?fmt(riskInfo.total_understocked)+' ':''}understocked best sellers · ${order}`;const t=document.getElementById('riskTip');if(t)t.setAttribute('data-tip',`Best sellers (Pareto 80% import revenue) with ≤ 8 weeks of coverage. Most urgent = earliest Order by date. ${riskInfo.comparison_available?'Stock compared with the snapshot of '+riskInfo.stock_prev_date+'.':'Only one stock snapshot so far, so there is no stock comparison yet.'} The bar marker is the 8-week lead time.`)}
document.querySelectorAll('#riskSort button').forEach(b=>b.addEventListener('click',()=>{riskMode=b.dataset.v;document.querySelectorAll('#riskSort button').forEach(x=>x.classList.toggle('active',x===b));updateRiskMeta();renderRisk(lastRisk,PT)}));
function applyRiskLimit(){const btn=document.getElementById('riskMore');if(btn)btn.hidden=true}
function toggleRiskAll(){riskShowAll=!riskShowAll;applyRiskLimit()}
let riskRaf=0;window.addEventListener('resize',()=>{cancelAnimationFrame(riskRaf);riskRaf=requestAnimationFrame(applyRiskLimit)});
function reviewSku(sku){switchTab('replenishment');openReplDetail(sku)}

/* ═══ TAB 2: FORECAST ═══ */
async function loadFcMap(){try{const r=await fetch('/api/forecast/results?limit=1000&fields=light');const d=await r.json();(d.results||[]).forEach(f=>{fcDataMap[f.sku]=f})}catch(e){}}
let weeklyByCat={},weeklyPromises={},weeklyShownCat=null;
function fetchWeekly(cat='import',scope='all'){const key=cat+'|'+scope;if(weeklyByCat[key])return Promise.resolve(weeklyByCat[key]);if(!weeklyPromises[key]){weeklyPromises[key]=(async()=>{if(!Object.keys(fcDataMap).length)await loadFcMap();const r=await fetch(`/api/weekly-analysis?product_type=${cat}&scope=${scope}`);if(!r.ok)throw new Error('Weekly analysis failed ('+r.status+')');const d=await r.json();weeklyByCat[key]={results:d.results||[],labels:d.week_labels||{}};return weeklyByCat[key]})().finally(()=>{delete weeklyPromises[key]})}return weeklyPromises[key]}
async function loadWeekly(){const cat=PT+'|'+bsScope();if(weeklyShownCat===cat&&weeklyByCat[cat]&&document.querySelector('#weeklyTableWrap table'))return;document.getElementById('weeklyTableWrap').innerHTML='<div class="loader-full"><span class="loading-spinner"></span> Loading...</div>';try{const d=await fetchWeekly(PT,bsScope());if(cat!==PT+'|'+bsScope())return;weeklyData=d.results;window._wl=d.labels;weeklyShownCat=cat;weeklyPage=0;filterWeekly()}catch(e){document.getElementById('weeklyTableWrap').innerHTML='<div class="empty-state">'+e.message+'</div>'}}
function filterWeekly(){const q=(document.getElementById('weeklySearch').value||'').toLowerCase(),t=cDropVal('weeklyTrend');let f=weeklyData;if(q)f=f.filter(r=>r.sku.toLowerCase().includes(q)||r.product_name.toLowerCase().includes(q));if(t)f=f.filter(r=>r.trend===t);renderWeeklyTable(f)}
function weeklyGoPage(p){weeklyPage=p;const q=(document.getElementById('weeklySearch').value||'').toLowerCase(),t=cDropVal('weeklyTrend');let f=weeklyData;if(q)f=f.filter(r=>r.sku.toLowerCase().includes(q)||r.product_name.toLowerCase().includes(q));if(t)f=f.filter(r=>r.trend===t);renderWeeklyTable(f);document.getElementById('weeklyTableWrap').scrollTop=0}
function renderWeeklyTable(data){closeSkuDetail();const wl=window._wl||{};const pages=Math.max(1,Math.ceil(data.length/PAGE_SIZE));if(weeklyPage>=pages)weeklyPage=0;const s=weeklyPage*PAGE_SIZE,pg=data.slice(s,s+PAGE_SIZE);
let h=`<table class="tbl-sticky"><thead><tr><th><div class="w-trend"></div></th><th><div class="w-sku">SKU</div></th><th><div class="w-prod">Product</div></th><th class="r">${wl.w2||'W-2'}</th><th class="r">${wl.w1||'W-1'}</th><th class="r" title="Units: last week minus the week before">Change</th><th class="r" title="Growth % last week vs the week before">Growth</th><th class="r" title="Average weekly sales over the last 4 weeks">Avg/Wk L4W</th><th class="r" title="Total units sold in the last 4 weeks">L4W Total</th><th class="r" title="Average forecast per week over the next 8 weeks (Holt's DES)">Forecast/Wk</th><th class="r" title="Forecast total for the next 4 weeks">Next 4W</th><th title="Average forecast next 8 weeks vs average actual last 8 weeks (±10% = stable)">Fc trend</th><th title="In-sample MAPE (fitted vs actual on the training data) — the thesis metric">MAPE</th><th title="Out-of-sample WMAPE: model trained without the last 8 weeks, then compared with them">WMAPE</th><th>Last weeks</th><th></th></tr></thead><tbody>`;
pg.forEach(r=>{const fc=fcDataMap[r.sku];const fcAvg=fc&&fc.fc_avg_8w!=null?fc.fc_avg_8w:'--';const fc4w=fc&&fc.forecast_data?fmt(Math.round(fc.forecast_data.quantities.slice(0,4).reduce((a,b)=>a+b,0))):'--';const mape=fc?fc.mape:null;const mc=mape!=null?(mape<25?'badge-green':mape<50?'badge-yellow':'badge-red'):'badge-gray';const ml=mape!=null?mape+'%':'--';const wm=fc?fc.holdout_wmape:null;const wc=wm!=null?(wm<25?'badge-green':wm<50?'badge-yellow':'badge-red'):'badge-gray';const wl=wm!=null?wm+'%':(fc?(fc.holdout_reason==='insufficient_history'?'short history':fc.holdout_reason==='not_computed'?'refresh':'n/a'):'--');
h+=`<tr class="clickable" data-sku="${r.sku}" onclick="loadSkuForecast('${r.sku}',this)"><td><div class="w-trend">${trendBadge(r.trend)}</div></td><td><div class="w-sku trunc t-strong">${r.sku}</div></td><td><div class="w-prod trunc t-strong" style="font-weight:500" title="${r.product_name.replace(/"/g,'&quot;')}">${r.product_name}</div></td><td class="r">${fmt(r.w2)}</td><td class="r t-strong">${fmt(r.w1)}</td><td class="r ${r.change>0?'num-pos':r.change<0?'num-neg':''}">${r.change>0?'+':''}${fmt(r.change)}</td><td class="r ${r.growth>0?'num-pos':r.growth<0?'num-neg':''}">${fmtPct(r.growth)}</td><td class="r t-strong">${r.avg_l4w}</td><td class="r">${fmt(r.l4w)}</td><td class="r t-strong">${fcAvg}</td><td class="r t-strong">${fc4w}</td><td>${fc?trendClassBadge(fc.trend_class,fc.trend_pct):'<span class="text-dim">--</span>'}</td><td><span class="badge ${mc}">${ml}</span></td><td><span class="badge ${wc}" title="${fc&&fc.holdout_reason?fc.holdout_reason:''}">${wl}</span></td><td>${sparklineSvg(r.sparkline)}</td><td>${ICON.chev}</td></tr>`});
h+='</tbody></table>';if(!pg.length)h='<div class="empty-state">No products match the filter.</div>';document.getElementById('weeklyTableWrap').innerHTML=h;renderPaging('weeklyPaging',weeklyPage,data.length,'weeklyGoPage')}

function closeSkuDetail(){const box=document.getElementById('skuDetailBox');if(box)box.style.display='none';document.querySelectorAll('#weeklyTableWrap tr.row-selected').forEach(t=>t.classList.remove('row-selected'));lastSku=null}
async function loadSkuForecast(sku,row){try{document.querySelectorAll('#weeklyTableWrap tr.row-selected').forEach(t=>t.classList.remove('row-selected'));if(row)row.classList.add('row-selected');
const r=await fetch(`/api/forecast/sku/${sku}`);const d=await r.json();lastSku=d;const box=document.getElementById('skuDetailBox');box.style.display='block';
document.getElementById('skuDetailName').textContent=d.product_name;
const lf=fcDataMap[d.sku]||{};const ho=d.holdout||{};
document.getElementById('skuInfo').innerHTML=`${d.sku} · α=${d.alpha} β=${d.beta} · MAPE (in-sample) <span class="${d.mape<25?'num-pos':d.mape<50?'':'num-neg'}">${d.mape}%</span> · WMAPE (holdout 8 wks) ${ho.wmape!=null?`<b>${ho.wmape}%</b> <span class="text-dim">α=${ho.alpha} β=${ho.beta}, ${ho.train_weeks} training weeks</span>`:`<span class="text-dim">${ho.reason==='insufficient_history'?'not enough history':'not computed yet — Refresh forecast'}</span>`} · Trend ${trendClassBadge(lf.trend_class,lf.trend_pct)}`;
renderSkuChart();
const fcq=d.forecast_data.quantities;const fc4=fcq.slice(0,4).reduce((a,b)=>a+b,0),fc8=fcq.slice(0,8).reduce((a,b)=>a+b,0),fc12=fcq.reduce((a,b)=>a+b,0),fcAvg=fcq.length?fc12/fcq.length:0;
const cell=(l,v,c='')=>`<div><div class="m-l">${l}</div><div class="m-v ${c}">${v}</div></div>`;
document.getElementById('skuFcKpis').innerHTML=cell('Next 4W',fmt(Math.round(fc4)))+cell('Next 8W',fmt(Math.round(fc8)))+cell(`Next ${fcq.length}W`,fmt(Math.round(fc12)))+cell('Avg / week',fmt(Math.round(fcAvg)))+cell('DES trend (β)',`${d.trend>0?'+':''}${d.trend}/w`,d.trend_direction==='up'?'trend-up':d.trend_direction==='down'?'trend-down':'trend-stable');
box.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){console.error(e)}}
function renderSkuChart(){const d=lastSku;if(!d)return;const ctx=document.getElementById('skuChart').getContext('2d');if(skuChartObj)skuChartObj.destroy();
const aw=d.actual_data.weeks,fw=d.forecast_data.weeks,all=[...aw,...fw];const aq=d.actual_data.quantities,fq=d.fitted_data.quantities,fcq=d.forecast_data.quantities;
const af=[...aq,...fw.map(()=>null)],ff=[...fq,...fw.map(()=>null)],fc2=[...aw.map(()=>null)];fc2[fc2.length-1]=aq[aq.length-1];fc2.push(...fcq);
const yMax=Math.max(...[...aq,...fcq].filter(v=>v!=null))*1.2;const c1=cv('--chart-1'),c2=cv('--chart-2'),c3=cv('--chart-3');
const o=baseOpts(v=>fmt(v),c=>`${c.dataset.label}: ${fmt(Math.round(c.parsed.y))}`);if(yMax>0)o.scales.y.max=Math.ceil(yMax);o.scales.x.ticks.maxRotation=0;
skuChartObj=new Chart(ctx,{type:'line',data:{labels:all.map(l=>String(l).substring(5)),datasets:[{label:'Actual',data:af,borderColor:c1,backgroundColor:areaFill(ctx,c1),fill:true,tension:.3,pointRadius:2,pointBackgroundColor:c1,borderWidth:2},{label:'Fitted (DES)',data:ff,borderColor:c3,borderDash:[3,3],tension:.3,pointRadius:0,borderWidth:1.5},{label:'Forecast',data:fc2,borderColor:c2,fill:false,borderDash:[6,4],tension:.3,pointRadius:2,pointBackgroundColor:c2,borderWidth:2}]},options:o})}

/* ═══ TAB 3: INVENTORY ═══ */
let invSeq=0;
async function loadInventory(){const sort=cDropVal('invSort')||'priority',cat=PT,seq=++invSeq;try{const r=await fetch(`/api/inventory?sort=${sort}&product_type=${cat}&scope=${bsScope()}`);const d=await r.json();if(seq!==invSeq)return;invData=d.results||[];const sm=d.summary||{};if(!BS)invSummaryCache=d.summary||invSummaryCache;
if(invData.length){document.getElementById('invKpis').style.display='block';countUp('ikUnder',sm.understocked||0,fmt);countUp('ikHealthy',sm.healthy||0,fmt);countUp('ikOver',sm.overstocked||0,fmt);
const items=[{v:sm.understocked||0,color:'var(--red)'},{v:sm.healthy||0,color:'var(--green)'},{v:sm.overstocked||0,color:'var(--slate)'}];document.getElementById('invRings').innerHTML=concentricSvg(items,items.reduce((a,b)=>a+b.v,0))}
document.getElementById('invSub').setAttribute('data-tip',(BS?'Best sellers (Pareto 80% revenue). ':'All products. ')+(d.stock_date?'Stock as of '+dfmt(d.stock_date)+'. ':'No stock data. ')+'Coverage = (stock + open PO) ÷ avg weekly sales of the last 4 weeks: ≤ 8 weeks Understocked · > 8–20 Healthy · > 20 Overstocked. Days of inventory = coverage × 7.');renderFresh(d.freshness);invPage=0;filterInv()}catch(e){document.getElementById('invTableWrap').innerHTML='<div class="empty-state">'+e.message+'</div>'}}
function invFiltered(){const q=(document.getElementById('invSearch').value||'').toLowerCase(),s=cDropVal('invStatus'),ao=document.getElementById('invActionOnly').checked;let f=invData;if(q)f=f.filter(r=>r.sku.toLowerCase().includes(q)||r.product_name.toLowerCase().includes(q));if(s)f=f.filter(r=>r.status===s);if(ao)f=f.filter(r=>r.status==='understocked');const mv=cDropVal('invMove');if(mv)f=f.filter(r=>r.movement===mv);return f}
function filterInv(){invPage=0;const st=cDropVal('invStatus');document.querySelectorAll('.inv-legend .lg').forEach(b=>b.classList.toggle('on',b.dataset.status===st));renderInvTable(invFiltered())}
function invGoPage(p){invPage=p;renderInvTable(invFiltered());document.getElementById('invTableWrap').scrollTop=0}
function renderInvTable(data){const s=invPage*PAGE_SIZE,pg=data.slice(s,s+PAGE_SIZE);
let h=`<table class="tbl-sticky"><thead><tr><th><div class="w-trend"></div></th><th><div class="w-sku">SKU</div></th><th><div class="w-prod">Product</div></th><th class="r" title="Revenue over the last 4 weeks">L4W Revenue</th><th class="r" title="Average weekly sales over the last 4 weeks">Avg/Wk L4W</th><th class="r" title="Physical stock, latest snapshot">Stock</th><th class="r" title="Outstanding quantity on open purchase orders">Open PO</th><th class="r" title="(Stock + open PO) ÷ avg weekly sales L4W">Coverage</th><th class="r" title="Coverage × 7">Days Inv.</th><th class="r" title="Stock × unit cost (weighted avg COGS, 12 weeks)">Value</th><th class="r" title="Units above 20 weeks of coverage">Overstock</th><th title="Rank of avg weekly units, last 12 weeks: top 20% fast, next 50% medium, rest slow">Movement</th><th class="r" title="Average forecast per week, next 8 weeks (Holt's DES)">Forecast/Wk</th><th class="r" title="First week the projected stock reaches 0 (open PO counted in its ETA week)">Stockout</th><th class="r col-reco" title="Recommended order quantity (see Replenishment)">Reco PO</th><th>Status</th></tr></thead><tbody>`;
pg.forEach(r=>{const tc=r.trend_class;const td=tc==='increasing'||tc==='new_demand'?'trend-up':tc==='decreasing'?'trend-down':'trend-stable';const ta=tc==='increasing'||tc==='new_demand'?'▲':tc==='decreasing'?'▼':tc?'▶':'';const so=r.stockout_week?`W${r.stockout_week}`:(r.forecasted?'> 12':'--');const soC=r.stockout_week&&r.stockout_week<=8?'num-neg':'';const covC=r.status==='understocked'?'num-neg':r.status==='overstocked'?'text-dim':'';const val=r.inventory_value!=null?fmtRpS(r.inventory_value):'<span class="text-dim" title="No unit cost">No cost</span>';
h+=`<tr class="clickable" onclick="openSkuDrawer('${String(r.sku).replace(/'/g,"\\'")}')"><td><div class="w-trend"><span class="${td}" title="${tc||'not forecasted'}">${ta}</span></div></td><td><div class="w-sku trunc t-strong">${esc(r.sku)}</div></td><td><div class="w-prod trunc t-strong" style="font-weight:500" title="${esc(r.product_name)}">${esc(r.product_name)}</div></td><td class="r">${fmtRp(r.l4w_revenue)}</td><td class="r t-strong">${r.avg_l4w}</td><td class="r ${r.current_stock<0?'num-neg':''}">${fmt(r.current_stock)}</td><td class="r">${r.ongoing_po?fmt(r.ongoing_po):'--'}</td><td class="r t-strong ${covC}">${r.coverage!=null?r.coverage.toFixed(1)+' w':'--'}</td><td class="r">${r.days_of_inventory!=null?fmt(Math.max(0,r.days_of_inventory))+' d':'--'}</td><td class="r">${val}</td><td class="r">${r.overstock_qty?fmt(r.overstock_qty):'--'}</td><td>${moveBadge(r.movement)}</td><td class="r">${r.fc_avg_weekly!=null?r.fc_avg_weekly:'--'}</td><td class="r t-strong ${soC}">${so}</td><td class="r col-reco">${r.reco_po>0?fmt(r.reco_po):'--'}</td><td>${statusBadge(r.status)}</td></tr>`});
h+='</tbody></table>';if(!pg.length)h='<div class="empty-state">No products match the filter.</div>';document.getElementById('invTableWrap').innerHTML=h;renderPaging('invPaging',invPage,data.length,'invGoPage')}

const csvCell=v=>v==null?'':(typeof v==='string'?`"${v.replace(/"/g,'""')}"`:v);
function downloadCsv(name,hdr,rows){const csv=hdr.join(',')+'\n'+rows.map(r=>r.map(csvCell).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}_${new Date().toISOString().slice(0,10)}.csv`;a.click()}
function exportInventory(){if(!invData.length)return;const hdr=['SKU','Product','L4W Revenue','Avg L4W/W','Stock','Open PO','Coverage (W)','Days of Inventory','Unit Cost','Cost Verified','Inventory Value','Overstock Qty','Overstock Value','Movement','Fc Avg/W','LT Demand 8W','Safety Stock','ROP','Stockout Week','Reco PO','Urgency','Status'];downloadCsv('inventory',hdr,invData.map(r=>[r.sku,r.product_name,r.l4w_revenue,r.avg_l4w,r.current_stock,r.ongoing_po,r.coverage,r.days_of_inventory,r.unit_cost,r.cost_verified?'yes':'no',r.inventory_value,r.overstock_qty,r.overstock_value,r.movement,r.fc_avg_weekly,r.lt_demand_8w,r.safety_stock,r.rop,r.stockout_week,r.reco_po,r.urgency,r.status||'not classified']))}
const REFRESH_HTML=document.getElementById('btnRefresh').innerHTML;
async function refreshForecast(){const btn=document.getElementById('btnRefresh');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span> Refreshing...';try{const rr=await fetch('/api/forecast/run',{method:'POST'});if(!rr.ok)throw new Error('Server returned '+rr.status);weeklyData=[];weeklyByCat={};weeklyShownCat=null;fcDataMap={};invSummaryCache=null;invOv=null;replData=null;scopeData=null;planData=null;await loadFcMap();if(anSub==='forecast'){if(dpView==='weekly')loadWeekly();else loadPlan()}else await loadInventory();toast('Forecast refreshed','success')}catch(e){toast('Refresh failed: '+e.message,'error')}btn.disabled=false;btn.innerHTML=REFRESH_HTML}

/* Server answered with something that is not JSON (e.g. Vercel timeout page): turn it into a readable error */
async function readJson(r){const t=await r.text();try{return JSON.parse(t)}catch(e){const msg=r.status===504||/timed out|FUNCTION_INVOCATION_TIMEOUT/i.test(t)?'The server took too long (time limit reached). Try again, or upload from the laptop.':(r.status>=500?`Server error (${r.status}). Try again in a moment.`:`Unexpected response (${r.status}).`);return{detail:msg}}}
/* ═══ TAB 4: ETL ═══ */
let etlFileId=null;
function etlMsg(html,type){const el=document.getElementById('etlStatus');el.style.display='block';el.className='card status-'+(type||'info');document.getElementById('etlStatusContent').innerHTML=html;const tmp=document.createElement('div');tmp.innerHTML=html;toast(tmp.textContent.split('\n')[0].slice(0,140),type)}
async function uploadSales(){const file=document.getElementById('salesFile').files[0];if(!file)return;const btn=document.getElementById('btnSalesUpload');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span> Uploading...';
const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/etl/upload',{method:'POST',body:fd});if(!r.ok){const e=await readJson(r);etlMsg(`<strong style="color:var(--red)">Error:</strong> ${JSON.stringify(e.detail)}`,'error');btn.disabled=false;btn.textContent='Upload Sales';return}
const d=await r.json();etlFileId=d.file_id;etlMsg(`<strong style="color:var(--green)">Parsed:</strong> ${d.filename} — ${fmt(d.stats?.clean_rows||0)} rows`,'success');
document.getElementById('etlPreview').style.display='block';document.getElementById('etlStats').innerHTML=`File: <strong>${d.filename}</strong> · Rows: <strong>${fmt(d.stats?.clean_rows||0)}</strong> · SKUs: <strong>${fmt(d.stats?.unique_skus||0)}</strong> · Products: <strong>${fmt(d.stats?.unique_products||0)}</strong>`;
let h='<table><thead><tr>';(d.columns||[]).forEach(c=>{h+=`<th>${c}</th>`});h+='</tr></thead><tbody>';(d.preview||[]).forEach(row=>{h+='<tr>';(d.columns||[]).forEach(c=>{h+=`<td>${row[c]!=null?row[c]:''}</td>`});h+='</tr>'});h+='</tbody></table>';document.getElementById('etlPreviewTable').innerHTML=h}catch(e){etlMsg(`<strong style="color:var(--red)">Upload failed:</strong> ${e.message}`,'error')}btn.disabled=false;btn.textContent='Upload Sales'}
async function confirmETL(){if(!etlFileId){etlMsg('No data to confirm','error');return}const btn=document.getElementById('btnConfirm');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span> Importing...';
try{const r=await fetch(`/api/etl/confirm/${etlFileId}`,{method:'POST'});const d=await readJson(r);if(r.ok){etlMsg(`<strong style="color:var(--green)">Imported:</strong> ${d.message}<br><span style="font-size:12px;color:var(--text3)">Forecast: ${d.forecast_status||'done'} · Products: ${d.database?.products} · Sales: ${fmt(d.database?.sales)}</span>`,'success');document.getElementById('etlPreview').style.display='none';etlFileId=null;weeklyData=[];weeklyByCat={};weeklyShownCat=null;invData=[];fcDataMap={};invSummaryCache=null}else{etlMsg(`<strong style="color:var(--red)">Error:</strong> ${d.detail||'Unknown error'}`,'error')}}catch(e){etlMsg(`<strong style="color:var(--red)">Import failed:</strong> ${e.message}`,'error')}btn.disabled=false;btn.innerHTML='Confirm &amp; Import'}
async function uploadStock(){const file=document.getElementById('stockFile').files[0];if(!file)return;const rd=document.getElementById('stockDate').value;if(!rd){toast('Pick the stock report date first','error');return}const btn=document.getElementById('btnStockUpload');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span>';const fd=new FormData();fd.append('file',file);fd.append('report_date',rd);try{const r=await fetch('/api/stock/upload',{method:'POST',body:fd});const d=await readJson(r);if(r.ok){etlMsg(`<strong style="color:var(--green)">Stock:</strong> ${d.message}`,'success');invSummaryCache=null;invOv=null;replData=null;loadDataStatus()}else etlMsg(`<strong style="color:var(--red)">Error:</strong> ${d.detail}`,'error')}catch(e){etlMsg(`Error: ${e.message}`,'error')}btn.disabled=false;btn.textContent='Upload Stock'}
async function uploadFood(){const file=document.getElementById('foodFile').files[0];if(!file)return;const btn=document.getElementById('btnFoodUpload');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span>';const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/food-sku/upload',{method:'POST',body:fd});const d=await readJson(r);if(r.ok){etlMsg(`<strong style="color:var(--green)">Food list saved:</strong> ${fmt(d.products_marked_food)} produk ditandai food (${fmt(d.auto_sku_matched_count)} di antaranya SKU AUTO- lewat nama).${d.sales_rows_archived?` · <b>${fmt(d.sales_rows_archived)}</b> baris penjualan food dikeluarkan dari sistem.`:''}${d.sales_rows_restored?` · ${fmt(d.sales_rows_restored)} baris dikembalikan (produk tidak lagi di daftar food).`:''}<br><span style="font-size:13px;color:var(--text3)">Upload penjualan berikutnya: baris produk food otomatis dikeluarkan. Jalankan Refresh forecast setelah ini.</span>`,'success');weeklyByCat={};weeklyShownCat=null;invSummaryCache=null;invOv=null;replData=null;planData=null;loadOverview()}else etlMsg(`<strong style="color:var(--red)">Error:</strong> ${d.detail}`,'error')}catch(e){etlMsg(`Error: ${e.message}`,'error')}btn.disabled=false;btn.textContent='Upload Food'}
async function uploadMaster(){const file=document.getElementById('masterFile').files[0];if(!file)return;const btn=document.getElementById('btnMasterUpload');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span>';const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/master-sku/upload',{method:'POST',body:fd});const d=await readJson(r);if(r.ok)etlMsg(`<strong style="color:var(--green)">Master SKU:</strong> ${fmt(d.products_synced)} SKU disinkronkan ke database`,'success');else etlMsg(`<strong style="color:var(--red)">Error:</strong> ${d.detail}`,'error')}catch(e){etlMsg(`Error: ${e.message}`,'error')}btn.disabled=false;btn.textContent='Upload Master'}

async function uploadHero(){const file=document.getElementById('heroFile').files[0];if(!file)return;const btn=document.getElementById('btnHeroUpload');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span>';const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/hero-sku/upload',{method:'POST',body:fd});const d=await readJson(r);if(r.ok){let m=`<strong style="color:var(--green)">Hero SKU:</strong> ${fmt(d.skus_saved)} SKU disimpan (${fmt(d.groups)} group).`;
if(d.bundles_split)m+=` ${d.bundles_split} kode bundle dipecah jadi SKU komponennya.`;if(d.normalized_count)m+=`<br><span style="font-size:12px;color:var(--text3)">${d.normalized_count} kode tanpa titik dicocokkan: ${d.normalized.slice(0,4).map(esc).join(', ')}${d.normalized_count>4?' ...':''}</span>`;
if(d.duplicates_skipped)m+=`<br><span style="font-size:12px;color:var(--text3)">${d.duplicates_skipped} baris duplikat dilewati.</span>`;if(d.new_products)m+=`<br><span style="font-size:12px;color:var(--text3)">${d.new_products} SKU belum ada di data produk, ditambahkan dari nama di file.</span>`;
if(d.unmatched_count)m+=`<br><span style="font-size:12px;color:var(--amber)">${d.unmatched_count} kode tidak dikenali: ${d.unmatched.slice(0,6).map(esc).join(', ')}</span>`;m+=`<br><span style="font-size:13px;color:var(--text3)">Klik <b>Refresh forecast</b> supaya semua SKU ini masuk analisis.</span>`;etlMsg(m,'success');scopeData=null;replData=null;invSummaryCache=null}else etlMsg(`<strong style="color:var(--red)">Error:</strong> ${esc(d.detail||'Upload failed')}`,'error')}catch(e){etlMsg(`Error: ${esc(e.message)}`,'error')}btn.disabled=false;btn.textContent='Upload Hero SKU'}

/* ═══ BEST-SELLER SCOPE (Overview) ═══ */
let scopeData=null,scopeMode='',scopePage=0,paretoChartObj=null;
async function loadScope(){try{const r=await fetch('/api/bestseller/scope');const d=await readJson(r);if(!r.ok)throw new Error(d.detail||'Scope request failed');scopeData=d;renderScope()}catch(e){document.getElementById('scopeStats').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
function renderScope(){const d=scopeData;if(!d)return;const p=d.pareto,h=d.hero,c=d.counts;
document.getElementById('scopeMeta').textContent=d.period.start?`Import revenue ${dfmt(d.period.start)} – ${dfmt(d.period.end)} · ${fmtRp(d.import_revenue)} · ${fmt(d.skus_sold)} SKUs sold`:'No import sales yet';
document.getElementById('scopeWarn').innerHTML=d.forecast_stale?'<div class="banner" style="background:var(--amber-bg);color:var(--amber);border-color:transparent">The company list changed after the last forecast. Run <b>Refresh forecast</b> on the Upload Data page so every listed SKU appears on the other pages.</div>':'';
const st=(l,v,s,cls)=>`<div class="scope-stat ${cls||''}"><div class="l">${l}</div><div class="v">${v}</div><div class="s">${s}</div></div>`;
document.getElementById('scopeStats').innerHTML=
 st('Pareto best sellers',fmt(p.skus),`${p.share_of_skus_pct}% of SKUs sold make ${p.revenue_pct}% of import revenue${p.cut_revenue!=null?` · cut-off ${fmtRp(p.cut_revenue)}`:''}`,'wide')
+st('Company Hero list',fmt(h.skus),h.skus?`${h.groups} groups · ${h.revenue_pct}% of import revenue`:'Not uploaded yet (Upload Data)')
+st('Analysed in Stockwise',fmt(c.in_system),`of ${fmt(c.in_scope)} in scope${c.naive?` · ${c.naive} with est. forecast`:''}`)
+st('On both lists',fmt(c.both),'Pareto and company agree')
+st('Company list only',fmt(c.hero_only),'Below the 80% cut or new: added by the company rule')
+st('Pareto only',fmt(c.pareto_only),'High revenue, not on the company list','wide');
const ctx=document.getElementById('paretoChart').getContext('2d');if(paretoChartObj)paretoChartObj.destroy();const c1=cv('--chart-1'),ct=getCT();
const pts=d.curve.map(x=>({x:x.rank,y:x.cum_pct})),last=d.skus_sold||1;
paretoChartObj=new Chart(ctx,{type:'line',data:{datasets:[{data:pts,borderColor:c1,backgroundColor:areaFill(ctx,c1),fill:true,pointRadius:0,borderWidth:2,tension:.2},{data:[{x:1,y:80},{x:last,y:80}],borderColor:ct.tick,borderDash:[5,4],borderWidth:1,pointRadius:0},{data:[{x:p.skus,y:0},{x:p.skus,y:100}],borderColor:ct.tick,borderDash:[5,4],borderWidth:1,pointRadius:0}]},
options:{responsive:true,maintainAspectRatio:false,parsing:true,interaction:{mode:'nearest',intersect:false},plugins:{legend:{display:false},tooltip:{filter:i=>i.datasetIndex===0,backgroundColor:ct.tipBg,titleColor:ct.tipTitle,bodyColor:ct.tipBody,borderColor:ct.tipBorder,borderWidth:1,callbacks:{title:i=>`Top ${fmt(i[0].parsed.x)} SKUs`,label:i=>`${i.parsed.y.toFixed(1)}% of import revenue`}}},
scales:{x:{type:'linear',min:1,max:last,grid:{display:false},border:{color:ct.grid},ticks:{color:ct.tick,font:ct.font,maxTicksLimit:6,callback:v=>fmt(v)},title:{display:true,text:'SKU rank by revenue',color:ct.tick,font:ct.font}},y:{min:0,max:100,grid:{color:ct.grid},border:{display:false},ticks:{color:ct.tick,font:ct.font,stepSize:20,callback:v=>v+'%'}}}}});
if(!document.getElementById('scopeListWrap').hidden)renderScopeList()}
function toggleScopeList(){const w=document.getElementById('scopeListWrap');w.hidden=!w.hidden;document.getElementById('scopeListBtn').textContent=w.hidden?'Show SKU list':'Hide SKU list';if(!w.hidden)renderScopeList()}
document.querySelectorAll('#scopeSeg button').forEach(b=>b.addEventListener('click',()=>{scopeMode=b.dataset.v;markSeg('scopeSeg',scopeMode);scopePage=0;renderScopeList()}));
function scopeGoPage(p){scopePage=p;renderScopeList()}
function renderScopeList(){if(!scopeData)return;const q=(document.getElementById('scopeSearch').value||'').toLowerCase().trim();let rows=scopeData.rows;if(scopeMode)rows=rows.filter(r=>r.source===scopeMode);if(q)rows=rows.filter(r=>[r.sku,r.product_name,r.group].some(x=>String(x||'').toLowerCase().includes(q)));
const src={both:'<span class="tag tag-hero">Pareto + company</span>',pareto:'<span class="tag tag-info">Pareto</span>',hero:'<span class="tag tag-warn">Company list</span>'};
const why={no_sales:'no sales yet',inactive:'no recent sales',too_few_weeks:'short history',forecast_fail:'could not fit'};
const fcCell=r=>!r.in_system?(r.hero?'<span class="tag tag-warn" title="Run Refresh forecast">not yet</span>':`<span class="text-dim" title="Pareto SKU left out of the forecast run">excluded · ${why[r.method_reason]||''}</span>`):r.method==='naive'?`<span class="tag tag-mute" title="${esc(naiveWhy(r.method_reason))}">est. · ${why[r.method_reason]||''}</span>`:"Holt's DES";
const st=scopePage*PAGE_SIZE,pg=rows.slice(st,st+PAGE_SIZE);
document.getElementById('scopeBody').innerHTML=pg.length?pg.map(r=>`<tr><td class="r text-dim">${r.rank??'--'}</td><td class="t-strong">${esc(r.sku)}</td><td><div class="trunc" style="max-width:260px" title="${esc(r.product_name||'')}">${esc(r.product_name||'-')}</div></td><td>${r.group?`<div class="trunc" style="max-width:200px" title="${esc(r.group)}">${esc(r.group)}</div><div class="ob-sub ob-none">${esc(r.status||'')}</div>`:'<span class="text-dim">--</span>'}</td><td class="r">${r.revenue?fmtRp(r.revenue):'--'}</td><td class="r">${r.share_pct?r.share_pct.toFixed(2)+'%':'--'}</td><td class="r ${r.cum_pct!=null&&r.cum_pct<=80?'':'text-dim'}">${r.cum_pct!=null?r.cum_pct.toFixed(1)+'%':'--'}</td><td>${src[r.source]}</td><td>${fcCell(r)}</td></tr>`).join(''):'<tr><td colspan="9"><div class="empty-state">No SKUs match.</div></td></tr>';
renderPaging('scopePaging',scopePage,rows.length,'scopeGoPage','SKUs')}

/* ═══ PURCHASE ORDERS ═══ */
async function uploadPO(){const file=document.getElementById('poFile').files[0];if(!file)return;const btn=document.getElementById('btnPoUpload');btn.disabled=true;btn.innerHTML='<span class="loading-spinner"></span>';const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/po/upload',{method:'POST',body:fd});const d=await readJson(r);if(r.ok&&d.new_lines!=null){let msg=`<strong style="color:var(--green)">PO list:</strong> ${esc(d.message)}`;if(d.warnings&&d.warnings.length)msg+=`<br><span style="font-size:12px;color:var(--amber)">${d.warnings.map(esc).join(' · ')}</span>`;msg+=`<br><span style="font-size:12px;color:var(--text3)">Upload ulang kapan saja: baris yang sama di-update, tidak dobel. Qty received yang sudah diisi di Stockwise tidak ditimpa angka yang lebih kecil.</span>`;etlMsg(msg,'success');invSummaryCache=null;replData=null;poData=[];loadPoPage()}else if(r.ok){let msg=`<strong style="color:var(--green)">PO:</strong> ${d.matched} loaded`;if(d.unmatched>0)msg+=` · <span style="color:var(--amber)">${d.unmatched} unmatched</span>`;if(d.unmatched_names?.length)msg+=`<br><span style="font-size:12px;color:var(--text3)">Unmatched: ${d.unmatched_names.slice(0,5).join(', ')}${d.unmatched_names.length>5?' ...':''}</span>`;if(d.warnings&&d.warnings.length)msg+=`<br><span style="font-size:12px;color:var(--text3)">${d.warnings.map(esc).join(' · ')}</span>`;if(d.column_mapping)msg+=`<br><span style="font-size:12px;color:var(--text3)">Columns: ${Object.entries(d.column_mapping).map(([k,v])=>esc(k)+' → '+v).join(', ')}</span>`;msg+=`<br><span style="font-size:12px;color:var(--text3)">Previously open lines were marked <b>superseded</b> (kept as history, not cancelled).</span>`;etlMsg(msg,'success');invSummaryCache=null;replData=null;loadPoPage()}else{etlMsg(`<strong style="color:var(--red)">Error:</strong> ${d.detail||'Upload failed'}`,'error')}}catch(e){etlMsg(`<strong style="color:var(--red)">PO upload failed:</strong> ${e.message}`,'error')}btn.disabled=false;btn.textContent='Upload PO'}
let poData=[],poMode='open',poView='po',poPage=0,poWarnDays=60,poOpenSku=new Set(),poByNum=new Map();
const PO_GROUPS_PER_PAGE=12,NO_PO='(no PO number)';
const poMo=d=>d==null?'--':(d/30.4).toFixed(1);
const todayIso=()=>{const t=new Date();t.setMinutes(t.getMinutes()-t.getTimezoneOffset());return t.toISOString().slice(0,10)};
const jsq=v=>String(v).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const PO_COLORS={pending:['var(--amber)','var(--amber-bg)'],partial:['var(--link)','var(--blue-bg)'],received:['var(--green)','var(--green-bg)'],completed:['var(--green)','var(--green-bg)'],closed:['var(--amber)','var(--amber-bg)'],cancelled:['var(--red)','var(--red-bg)'],superseded:['var(--text3)','var(--surface2)']};
function poBadge(s){const c=PO_COLORS[s]||['var(--text3)','var(--surface2)'];return`<span class="badge" style="color:${c[0]};background:${c[1]};text-transform:capitalize" ${s==='superseded'?'title="Replaced by a later PO upload (not a cancellation)"':s==='closed'?'title="Closed short: the rest will not arrive"':''}>${s}</span>`}
function poIndex(){poByNum=new Map();poData.forEach(p=>{const k=p.po_number||NO_PO;if(!poByNum.has(k))poByNum.set(k,[]);poByNum.get(k).push(p)})}
function poRecalc(p){const t=todayIso();p.remaining=p.qty_ordered-p.qty_received;p.is_open=['pending','partial'].includes(p.status)&&p.remaining>0;p.outstanding=p.is_open?p.remaining:0;
p.overdue=!!(p.is_open&&p.eta&&p.eta<t);p.days_overdue=p.overdue?Math.round((new Date(t)-new Date(p.eta))/864e5):null;
const end=(!p.is_open&&p.received_date)?p.received_date:t;p.age_days=p.order_date?Math.round((new Date(end)-new Date(p.order_date))/864e5):null;p.aging=!!(p.is_open&&p.age_days!=null&&p.age_days>poWarnDays)}
function poState(p){const rem=p.remaining;
if(p.status==='cancelled')return'<span class="badge badge-gray">Cancelled</span>';
if(rem<0)return`<span class="badge badge-yellow" title="${fmt(-rem)} units more than ordered">Over +${fmt(-rem)}</span>`;
if(rem===0)return'<span class="badge badge-green">Complete</span>';
if(!p.is_open)return`<span class="badge badge-yellow" title="Closed: the remaining ${fmt(rem)} units will not arrive">Closed short −${fmt(rem)}</span>`;
if(!p.qty_received)return'<span class="badge badge-gray">Not received</span>';
return`<span class="badge badge-blue" title="${fmt(rem)} units still to arrive">Partial −${fmt(rem)}</span>`}
function poFilter(p){switch(poMode){case'open':return p.is_open;case'overdue':return p.overdue;case'aging':return p.aging;case'diff':return p.status!=='cancelled'&&p.qty_received>0&&p.remaining!==0;case'done':return!p.is_open&&p.status!=='cancelled';default:return true}}
function poAge(d,warn){if(d==null)return'<span class="text-dim">--</span>';return`<div class="ob-date ${warn?'ob-late':'ob-ok'}" ${warn?`title="Open more than ${poWarnDays} days since the PO date"`:''}>${fmt(d)} d${warn?` <span class="tag tag-late">&gt; ${poWarnDays} d</span>`:''}</div><div class="ob-sub ob-none">${poMo(d)} months</div>`}
function poEta(p){if(!p.is_open)return`<span class="text-dim">${p.eta?dfmt(p.eta):'--'}</span>`;if(p.eta_source==='unknown')return'<span class="tag tag-warn" title="No ETA and no PO date: not counted as incoming">Unknown</span>';return`${dfmt(p.eta)}${p.eta_source==='estimated'?' <span class="tag tag-info" title="PO date + default lead time">est.</span>':''}${p.overdue?`<div class="ob-sub ob-late">${p.days_overdue} days late</div>`:''}`}
function poRecv(p){if(p.status==='cancelled')return fmt(p.qty_received);return`<input class="qty-in" type="number" min="0" step="1" value="${p.qty_received}" onchange="setPoReceived(${p.id},this)" onclick="event.stopPropagation()" aria-label="Qty received for ${esc(p.sku)}">`}
function poRecvDate(p){if(!p.qty_received)return'<span class="text-dim">--</span>';return`<input type="date" class="date-mini" value="${p.received_date||''}" max="${todayIso()}" onchange="setPoRecvDate(${p.id},this.value)" onclick="event.stopPropagation()" aria-label="Receipt date">`}
function poAct(p){if(p.is_open)return p.qty_received>0?`<button class="mini-btn" title="The rest will not arrive: close this line (stops counting it as incoming)" onclick="setPoStatus(${p.id},'closed')">Close short</button>`:`<button class="mini-btn" style="color:var(--text3)" title="Nothing will arrive: cancel this line" onclick="setPoStatus(${p.id},'cancelled')">Cancel</button>`;
if(p.status==='closed'||p.status==='cancelled')return`<button class="mini-btn" onclick="setPoStatus(${p.id},'reopen')">Reopen</button>`;return''}
function skuBtn(sku){return`<button class="link-btn" style="font-size:14px;margin:0" onclick="event.stopPropagation();openSkuDrawer('${jsq(sku)}')">${esc(sku||'-')}</button>`}
async function loadPoList(){try{const r=await fetch('/api/po/list?status=all');const d=await readJson(r);if(!r.ok)throw new Error(d.detail||'PO list failed');poData=d.data||[];poWarnDays=d.aging_warn_days||60;poIndex();
document.getElementById('poAgingL').innerHTML=`Open &gt; ${poWarnDays} Days`;document.querySelector('#poStatusSeg [data-v="aging"]').innerHTML=`&gt; ${poWarnDays} days`;renderPoTable()}catch(e){console.error('PO list:',e);document.getElementById('poEmpty').textContent=e.message;document.getElementById('poEmpty').style.display='block'}}
async function loadPoSummary(){try{const r=await fetch('/api/po/summary');const d=await readJson(r);if(!r.ok)throw new Error(d.detail||'PO summary failed');
countUp('poOpen',d.open_po_numbers??d.open_pos??0,fmt);document.getElementById('poOpenSub').textContent=`${fmt(d.open_pos||0)} open lines`;
countUp('poIncoming',d.outstanding_qty||0,fmt);countUp('poOverdue',d.overdue||0,fmt);countUp('poAging',d.aging||0,fmt);
document.getElementById('poIncomingSub').textContent=`units still to arrive${d.eta_unknown?` · ${d.eta_unknown} lines without ETA`:''}`;
const lt=d.lead_time||{},defD=(d.default_lead_time_weeks||8)*7,pl=document.getElementById('poLead');pl.classList.remove('skel');
if(lt.available){pl.textContent=`${Math.round(lt.median_days??lt.avg_days)} days`;pl.style.color=(lt.p90_days||0)>defD?'var(--amber)':'';document.getElementById('poLeadSub').textContent=`median · p90 ${lt.p90_days} d · plan assumes ${defD} d`}
else{pl.textContent=`${d.default_lead_time_weeks} weeks`;pl.style.color='';document.getElementById('poLeadSub').textContent='default assumption (no receipts yet)'}
const f=d.fulfillment||{},so=d.stockout_rate||{};const card=(on,l,v,sub)=>`<div class="perf-card ${on?'on':''}"><div class="p-l">${l}</div><div class="p-v">${on?v:'<span class="tag tag-mute">Not enough data</span>'}</div><div class="p-s">${sub}</div></div>`;
const sup=(lt.by_supplier||[]).filter(x=>x.std_days!=null);
document.getElementById('perfGrid').innerHTML=card(f.available,'PO Fill Rate',f.rate_pct+'%',f.available?`Received ÷ ordered (over-delivery capped), ${fmt(f.po_lines)} due lines · ${fmt(f.short_lines||0)} short, ${fmt(f.over_lines||0)} over`:'Needs received quantities on PO lines that are due.')
+card(lt.available,'Actual Lead Time',`${lt.avg_days} days`,lt.available?`Average PO date → receipt date, ${fmt(lt.deliveries)} received lines · median ${lt.median_days} d`:'Needs PO date and receipt date on the same line.')
+card(sup.length>0,'Lead Time Variance',sup.length?sup.map(x=>`±${x.std_days} days`).slice(0,1).join(''):'',sup.length?`Standard deviation, ${esc(sup[0].supplier)}`:'Needs at least 3 received lines.')
+card(so.available,'Stockout Rate',so.rate_pct+'%',so.available?`SKU-weeks with stock ≤ 0, best sellers, last ${so.weeks} weeks`:`Needs ≥ ${so.required||4} weekly stock snapshots (have ${so.snapshots||0}).`)}catch(e){console.error('PO summary:',e)}}
async function loadPoPage(){loadPoList();loadPoSummary()}
document.querySelectorAll('#poStatusSeg button').forEach(b=>b.addEventListener('click',()=>{poMode=b.dataset.v;markSeg('poStatusSeg',poMode);poPage=0;renderPoTable()}));
document.querySelectorAll('#poViewSeg button').forEach(b=>b.addEventListener('click',()=>{poView=b.dataset.v;markSeg('poViewSeg',poView);poPage=0;renderPoTable()}));
function poGoPage(p){poPage=p;renderPoTable();document.getElementById('poSection').scrollIntoView({block:'start',behavior:'smooth'})}
function renderPoTable(){const empty=document.getElementById('poEmpty'),table=document.getElementById('poTable');
if(!poData.length){empty.style.display='block';table.style.display='none';document.getElementById('poPaging').innerHTML='';return}empty.style.display='none';table.style.display='table';
const q=(document.getElementById('poSearch').value||'').toLowerCase().trim();let rows=poData.filter(poFilter);
if(q)rows=rows.filter(p=>[p.sku,p.product,p.po_number].some(x=>String(x||'').toLowerCase().includes(q)));
poView==='po'?renderPoByPo(rows):renderPoBySku(rows)}
function renderPoByPo(rows){
document.getElementById('poHead').innerHTML=`<tr><th>SKU</th><th>Product</th><th class="r">Ordered</th><th class="r" title="Type the quantity that actually arrived">Received</th><th>Status</th><th title="Expected date; est. = PO date + default lead time">ETA</th><th title="Date the goods arrived (editable, used for actual lead time)">Received on</th><th title="Days since PO date (until receipt for finished lines)">PO age</th><th></th></tr>`;
const g=new Map();rows.forEach(p=>{const k=p.po_number||NO_PO;if(!g.has(k))g.set(k,[]);g.get(k).push(p)});
const groups=[...g.entries()].map(([k,ls])=>{const all=poByNum.get(k)||ls;return{k,ls,all,open:all.some(x=>x.is_open),date:all.map(x=>x.order_date).filter(Boolean).sort()[0]||''}}).sort((a,b)=>(b.open-a.open)||b.date.localeCompare(a.date));
const st=poPage*PO_GROUPS_PER_PAGE,pg=groups.slice(st,st+PO_GROUPS_PER_PAGE);
document.getElementById('poBody').innerHTML=pg.length?pg.map(G=>{const all=G.all.filter(x=>x.status!=='cancelled'),ord=all.reduce((s,x)=>s+x.qty_ordered,0),rec=all.reduce((s,x)=>s+Math.min(x.qty_received,x.qty_ordered),0),pct=ord?Math.round(rec/ord*100):0;
const openL=all.filter(x=>x.is_open),age=openL.length?Math.max(...openL.map(x=>x.age_days||0)):null,aging=openL.some(x=>x.aging),late=openL.filter(x=>x.overdue).length,over=all.filter(x=>x.remaining<0).length;
const head=`<tr class="po-grp"><td colspan="9"><div class="po-grp-in"><b>${esc(G.k)}</b><span class="text-dim">${G.date?dfmt(G.date):'no PO date'}</span><span class="po-prog" title="${pct}% received"><i style="width:${pct}%"></i></span><span class="text-dim">${fmt(rec)} / ${fmt(ord)} pcs · ${all.length-openL.length}/${all.length} lines done</span>${openL.length?`<span class="tag tag-info">${openL.length} open</span>`:'<span class="badge badge-green">Complete</span>'}${aging?`<span class="tag tag-late" title="Open more than ${poWarnDays} days">${fmt(age)} days · ${poMo(age)} months</span>`:age!=null?`<span class="text-dim">${fmt(age)} days</span>`:''}${late?`<span class="tag tag-late">${late} past ETA</span>`:''}${over?`<span class="tag tag-warn">${over} over</span>`:''}${openL.length?`<button class="btn btn-ghost btn-xs" style="margin-left:auto" onclick="receiveAllPo('${jsq(G.k)}')" ${G.k===NO_PO?'disabled':''}>Mark all received</button>`:''}</div></td></tr>`;
return head+G.ls.map(p=>`<tr><td class="t-strong">${skuBtn(p.sku)}</td><td><div class="trunc" style="max-width:240px" title="${esc(p.product||'')}">${esc(p.product||'-')}</div></td><td class="r t-strong">${fmt(p.qty_ordered)}</td><td class="r">${poRecv(p)}</td><td>${poState(p)}</td><td>${poEta(p)}</td><td>${poRecvDate(p)}</td><td>${poAge(p.age_days,p.aging)}</td><td>${poAct(p)}</td></tr>`).join('')}).join(''):'<tr><td colspan="9"><div class="empty-state">No PO lines match.</div></td></tr>';
renderPaging('poPaging',poPage,groups.length,'poGoPage','POs',PO_GROUPS_PER_PAGE)}
function renderPoBySku(rows){
document.getElementById('poHead').innerHTML=`<tr><th style="width:28px"></th><th>SKU</th><th>Product</th><th>PO lines</th><th class="r" title="Open PO lines for this SKU">Total PO Aktif</th><th class="r" title="Units still to arrive (ordered − received) on open lines">Total QTY</th><th title="Oldest open line, days since PO date">PO Age (days)</th><th class="r">PO Age (months)</th></tr>`;
const m=new Map();rows.forEach(p=>{if(!m.has(p.sku))m.set(p.sku,[]);m.get(p.sku).push(p)});
const items=[...m.entries()].map(([sku,ls])=>{const open=ls.filter(x=>x.is_open);return{sku,name:ls[0].product,ls,openN:open.length,qty:open.reduce((s,x)=>s+x.outstanding,0),age:open.length?Math.max(...open.map(x=>x.age_days||0)):null,aging:open.some(x=>x.aging)}}).sort((a,b)=>(b.age??-1)-(a.age??-1)||b.qty-a.qty);
const st=poPage*PAGE_SIZE,pg=items.slice(st,st+PAGE_SIZE);
document.getElementById('poBody').innerHTML=pg.length?pg.map(it=>{const open=poOpenSku.has(it.sku),k=jsq(it.sku);
const mini=it.ls.slice(0,3).map(x=>`${esc(x.po_number||'-')} · ${x.order_date?dfmt(x.order_date):'--'} · ${fmt(x.qty_ordered)} pcs`).join('<br>')+(it.ls.length>3?`<br>+${it.ls.length-3} more`:'');
let h=`<tr class="po-sku-row ${open?'open':''}" onclick="togglePoSku('${k}')"><td><span class="chev">&#8250;</span></td><td class="t-strong">${skuBtn(it.sku)}</td><td><div class="trunc" style="max-width:240px" title="${esc(it.name||'')}">${esc(it.name||'-')}</div></td><td><div class="po-mini">${mini}</div></td><td class="r t-strong">${it.openN||'--'}</td><td class="r t-strong">${it.qty?fmt(it.qty):'--'}</td><td>${it.age!=null?poAge(it.age,it.aging):'<span class="text-dim">--</span>'}</td><td class="r ${it.aging?'ob-late':''}" style="font-weight:600">${it.age!=null?poMo(it.age):'--'}</td></tr>`;
if(open)h+=`<tr class="po-sub-wrap"><td colspan="8"><table class="po-sub"><thead><tr><th>PO number</th><th>PO date</th><th class="r">Ordered</th><th class="r">Received</th><th>Status</th><th>ETA</th><th>Received on</th><th>PO age</th><th></th></tr></thead><tbody>${it.ls.map(p=>`<tr><td class="t-strong">${esc(p.po_number||'-')}</td><td>${p.order_date?dfmt(p.order_date):'--'}</td><td class="r">${fmt(p.qty_ordered)}</td><td class="r">${poRecv(p)}</td><td>${poState(p)}</td><td>${poEta(p)}</td><td>${poRecvDate(p)}</td><td>${poAge(p.age_days,p.aging)}</td><td>${poAct(p)}</td></tr>`).join('')}</tbody></table></td></tr>`;return h}).join(''):'<tr><td colspan="8"><div class="empty-state">No PO lines match.</div></td></tr>';
renderPaging('poPaging',poPage,items.length,'poGoPage','products')}
function togglePoSku(sku){poOpenSku.has(sku)?poOpenSku.delete(sku):poOpenSku.add(sku);renderPoTable()}
async function patchPo(id,body,okMsg){try{const r=await fetch('/api/po/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await readJson(r);if(!r.ok)throw new Error(d.detail||'Update failed');
const p=poData.find(x=>x.id===id);if(p){p.qty_received=d.qty_received;p.status=d.line_status;p.received_date=d.received_date;poRecalc(p)}
invSummaryCache=null;replData=null;renderPoTable();loadPoSummary();if(okMsg&&p)toast(okMsg(p),'success')}catch(e){toast(e.message,'error');renderPoTable()}}
function setPoReceived(id,el){const v=Number(el.value);if(!Number.isInteger(v)||v<0){toast('Received must be a whole number ≥ 0','error');renderPoTable();return}
patchPo(id,{qty_received:v},p=>`${p.sku}: ${fmt(p.qty_received)} of ${fmt(p.qty_ordered)} received${p.remaining<0?` (over +${fmt(-p.remaining)})`:p.remaining>0?` (${fmt(p.remaining)} to come)`:''}`)}
function setPoRecvDate(id,v){if(!v)return;patchPo(id,{received_date:v},p=>`${p.sku}: receipt date ${dfmt(v)}`)}
function setPoStatus(id,s){patchPo(id,{status:s},p=>`${p.sku}: ${s==='reopen'?'reopened':s==='closed'?'closed short':s}`)}
async function receiveAllPo(po){const n=(poByNum.get(po)||[]).filter(x=>x.is_open).length;if(!confirm(`Mark all ${n} open lines of ${po} as fully received today?\n(Edit a line afterwards if something was short.)`))return;
try{const r=await fetch('/api/po/receive-all',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({po_number:po})});const d=await readJson(r);if(!r.ok)throw new Error(d.detail||'Update failed');toast(`${po}: ${d.lines} lines marked received`,'success');invSummaryCache=null;replData=null;loadPoPage()}catch(e){toast(e.message,'error')}}


/* ═══ REPLENISHMENT ═══ */
let replData=null,replPage=0,replStatus='',replTab='reorder',replSeq=0;
const needOrder=r=>(r.reco_po||0)>0||r.status==='understocked'||(r.order_by_days!=null&&!r.order_by_is_estimate&&r.order_by_days<=14);
function orderByCell(r,compact){if(!r.order_by)return'<span class="text-dim">--</span>';const d=r.order_by_days;
if(r.order_by_is_estimate)return`<div class="ob-date ob-none">${compact?'':'not before '}${dfmt(r.order_by)}</div><div class="ob-sub ob-none">stock lasts &gt; 12 wks</div>`;
const cls=d<0?'ob-late':d<=14?'ob-soon':'ob-ok';const sub=d<0?`${-d} days overdue`:d===0?'today':`in ${d} days`;return`<div class="ob-date ${cls}">${dfmt(r.order_by)}</div><div class="ob-sub ${cls}">${sub}</div>`}
async function loadReplenishment(){const seq=++replSeq,pt=PT;if(replData&&replData._pt===pt){renderRepl();return}document.getElementById('rpTableWrap').innerHTML='<div class="loader-full"><span class="loading-spinner"></span> Loading...</div>';try{const r=await fetch(`/api/replenishment?product_type=${pt}`);if(!r.ok)throw new Error('Replenishment request failed ('+r.status+')');const d=await r.json();if(seq!==replSeq)return;d._pt=pt;
(d.results||[]).forEach(x=>{x.qty=x.reco_po||0;x.sel=needOrder(x)&&(x.reco_po||0)>0});replData=d;renderFresh(d.freshness);const st=d.settings||{};
document.getElementById('rpSub').setAttribute('data-tip',`What to buy, by when, and how much. Follow the Order by date: projected stockout date minus the ${st.lead_time_weeks}-week supplier lead time (default), so the goods arrive before stock runs out.\n\nUnits to order starts at the system recommendation: forecast over the lead time + safety stock (${Math.round((st.ss_pct||0)*100)}% of the ${st.ss_basis_weeks}-week forecast) − (stock + open PO with an ETA). You can change it; the recommendation stays visible.\n\n${d.stock_date?'Stock as of '+dfmt(d.stock_date)+'. ':''}Review every ${st.review_period_days} days. The system recommends; purchasing decides.`);
document.getElementById('sbCostL').innerHTML='estimated cost'+((d.summary||{}).cost_verified?'':' · <span title="Unit cost from cogs_accurate, not yet confirmed by finance">unverified</span>');
replPage=0;renderRepl()}catch(e){document.getElementById('rpTableWrap').innerHTML='<div class="empty-state">'+esc(e.message)+'</div>'}}
document.querySelectorAll('#rpStatus button').forEach(b=>b.addEventListener('click',()=>{replStatus=b.dataset.v;markSeg('rpStatus',replStatus);replPage=0;renderRepl()}));
document.querySelectorAll('#rpTabs button').forEach(b=>b.addEventListener('click',()=>{replTab=b.dataset.v;document.querySelectorAll('#rpTabs button').forEach(x=>x.classList.toggle('active',x===b));replPage=0;renderRepl()}));
function replFiltered(){if(!replData)return[];const q=(document.getElementById('rpSearch').value||'').toLowerCase();let f=replData.results||[];if(replTab==='reorder')f=f.filter(needOrder);if(replStatus)f=f.filter(r=>r.status===replStatus);if(replSource==='hero')f=f.filter(r=>['hero','both'].includes(r.scope_source));else if(replSource==='pareto')f=f.filter(r=>r.scope_source==='pareto');if(q)f=f.filter(r=>r.sku.toLowerCase().includes(q)||r.product_name.toLowerCase().includes(q)||String(r.hero_group||'').toLowerCase().includes(q));return f}
let replSource='';document.querySelectorAll('#rpSource button').forEach(b=>b.addEventListener('click',()=>{replSource=b.dataset.v;markSeg('rpSource',replSource);replPage=0;renderRepl()}));
function scopeTags(r){let t='';if(r.scope_source==='hero'||r.scope_source==='both'){const up=/upris/i.test(r.hero_status||'');t+=` <span class="tag ${up?'tag-up':'tag-hero'}" title="${esc((r.hero_status||'Company list')+(r.hero_group?' · '+r.hero_group:''))}">${up?'Uprising':'Hero'}</span>`}if(r.fc_method==='naive')t+=` <span class="tag tag-mute" title="${esc(naiveWhy(r.fc_method_reason))}">est.</span>`;return t}
function naiveWhy(k){return{no_sales:'No import sales yet: forecast is 0 until it sells',inactive:'Few or no sales in recent weeks: forecast = average of the last 4 weeks',too_few_weeks:'Less than 4 weeks of history: forecast = average so far',forecast_fail:"Holt's DES could not fit: forecast = average of the last 4 weeks"}[k]||'Simple average forecast'}
function replGoPage(p){replPage=p;renderRepl()}
function replRow(sku){return(replData&&replData.results||[]).find(x=>x.sku===sku)}
function setReplQty(sku,v){const r=replRow(sku);if(!r)return;r.qty=Math.max(0,Math.round(Number(v)||0));if(r.qty>0)r.sel=true;renderRepl()}
function setReplSel(sku,v){const r=replRow(sku);if(r){r.sel=v;renderRepl()}}
function setReplAll(v){replFiltered().forEach(r=>r.sel=v);renderRepl()}
function renderRepl(){const all=replData?replData.results||[]:[];document.getElementById('rpCntAll').textContent=fmt(all.length);document.getElementById('rpCntRe').textContent=fmt(all.filter(needOrder).length);
const data=replFiltered(),st=replPage*PAGE_SIZE,pg=data.slice(st,st+PAGE_SIZE);
let h=`<table class="ro-table"><thead><tr><th style="width:34px"><input type="checkbox" class="cb" ${data.length&&data.every(r=>r.sel)?'checked':''} onclick="event.stopPropagation();setReplAll(this.checked)" aria-label="Select all"></th><th>Product</th><th title="Physical stock; below it the open PO quantity on the way">Total stock</th><th class="r" title="Coverage × 7 · coverage = (stock + open PO) ÷ avg weekly sales, last 4 weeks">Days of cover</th><th title="Projected stockout date − supplier lead time. After this date the order arrives after stock runs out.">Order by</th><th title="≤ 8 weeks Understocked · > 8–20 Healthy · > 20 Overstocked">Status</th><th class="r" title="Starts at the system recommendation; you can change it">Units to order</th></tr></thead><tbody>`;
pg.forEach(r=>{const sk=String(r.sku).replace(/'/g,"\\'");const edited=r.qty!==(r.reco_po||0);const reco=r.reco_po||0;
const hint=edited?`system ${fmt(reco)} · <button class="reset-btn" onclick="event.stopPropagation();setReplQty('${sk}',${reco})">reset</button>`:(reco?'system recommendation':((r.reco_order_up_to||0)>0&&r.order_by_days!=null&&!r.order_by_is_estimate&&r.order_by_days<=28?`<span style="color:var(--amber)" title="The thesis formula only covers the lead time. With the next review in 2 weeks, order-up-to suggests ${fmt(r.reco_order_up_to)}.">system 0 · order-up-to ${fmt(r.reco_order_up_to)}</span>`:'no order needed'));
h+=`<tr class="${r.sel?'sel':''}" onclick="openReplDetail('${sk}',this)"><td onclick="event.stopPropagation()"><input type="checkbox" class="cb" ${r.sel?'checked':''} onchange="setReplSel('${sk}',this.checked)" aria-label="Select ${esc(r.product_name)}"></td>
<td><div class="p-name" title="${esc(r.product_name)}">${esc(r.product_name)}</div><div class="p-sku">${esc(r.sku)}${scopeTags(r)}</div></td>
<td><div class="stk-main ${r.current_stock<=0?'num-neg':''}">${fmt(r.current_stock)} available</div><div class="stk-sub">${fmt(r.confirmed_incoming||0)} in transit${r.unconfirmed_incoming?` · <span class="unk" title="Open PO without ETA — not counted until confirmed">+${fmt(r.unconfirmed_incoming)} ETA ?</span>`:''}</div></td>
<td class="r"><b>${r.days_of_inventory!=null?fmt(Math.max(0,r.days_of_inventory))+' days':'--'}</b></td>
<td>${orderByCell(r)}</td><td>${statusBadge(r.status)}</td>
<td class="r" onclick="event.stopPropagation()"><input class="qty-in ${edited?'edited':''}" type="number" min="0" step="10" value="${r.qty}" onchange="setReplQty('${sk}',this.value)" aria-label="Units to order"><div class="qty-hint">${hint}</div></td></tr>`});
h+='</tbody></table>';if(!replData)h='<div class="empty-state">Loading...</div>';else if(!all.length)h='<div class="empty-state">No forecasted best sellers yet. Upload sales data and run Refresh forecast.</div>';else if(!pg.length)h='<div class="empty-state">No SKUs match the filter.</div>';
document.getElementById('rpTableWrap').innerHTML=h;renderPaging('rpPaging',replPage,data.length,'replGoPage');
const sel=all.filter(r=>r.sel);document.getElementById('sbCount').textContent=`${fmt(sel.length)} SKU${sel.length===1?'':'s'}`;document.getElementById('sbUnits').textContent=fmt(sel.reduce((a,r)=>a+r.qty,0));const noc=sel.filter(r=>r.qty>0&&r.unit_cost==null).length;document.getElementById('sbCost').textContent=fmtRpS(sel.reduce((a,r)=>a+(r.unit_cost?r.qty*r.unit_cost:0),0))+(noc?` +${noc} no cost`:'')}
function exportReplenishment(selectedOnly){const d=selectedOnly?(replData&&replData.results||[]).filter(r=>r.sel&&r.qty>0):replFiltered();if(!d.length){toast(selectedOnly?'Select at least one SKU with units to order':'Nothing to export','info');return}
downloadCsv(selectedOnly?'order_plan':'replenishment',['SKU','Product','Status','Stock','In transit (ETA known)','Open PO without ETA','Days of cover','Order by','Order by is estimate','System recommendation','Units to order','Changed manually','Order-up-to (comparison)','Unit cost','Cost verified','Estimated cost'],d.map(r=>[r.sku,r.product_name,r.status||'not classified',r.current_stock,r.confirmed_incoming,r.unconfirmed_incoming,r.days_of_inventory,r.order_by,r.order_by_is_estimate?'yes':'no',r.reco_po,r.qty,r.qty!==(r.reco_po||0)?'yes':'no',r.reco_order_up_to,r.unit_cost,r.cost_verified?'yes':'no',r.unit_cost!=null?Math.round(r.qty*r.unit_cost):'']))}
async function openReplDetail(sku,row){document.querySelectorAll('#rpTableWrap tr.row-selected').forEach(t=>t.classList.remove('row-selected'));if(row)row.classList.add('row-selected');const box=document.getElementById('rpDetail');box.style.display='block';box.innerHTML='<div class="loader-full"><span class="loading-spinner"></span> Loading...</div>';
try{const r=await fetch(`/api/replenishment/sku/${encodeURIComponent(sku)}`);const d=await r.json();if(!r.ok)throw new Error(d.detail||'Not found');const p=d.plan,uc=d.unit_cost;
const cell=(l,v,sub='')=>`<div><div class="d-l">${l}</div><div class="d-v">${v}</div>${sub?`<div class="d-s">${sub}</div>`:''}</div>`;
const pr=p.projection||[];const row=(l,k,cls)=>`<tr><td>${l}</td>${pr.map(w=>{const v=w[k];const c=cls?cls(w):'';return`<td class="${c}">${v?fmt(Math.round(v)):(k==='closing'||k==='opening'?'0':'')}</td>`}).join('')}</tr>`;
const pol=(p.po_lines||[]);const sc=d.safety_stock_comparison||{};
box.innerHTML=`<div class="card-header"><div><div class="section-label">${esc(d.product_name)}</div><div class="section-meta">${esc(d.sku)} · stock ${fmt(d.current_stock)} as of ${d.stock_date||'--'} · forecast trend ${trendClassBadge(d.forecast.trend_class,d.forecast.trend_pct)}</div></div><div style="display:flex;gap:8px;align-items:center">${statusBadge((replRow(d.sku)||{}).status)}<button class="btn btn-ghost" onclick="document.getElementById('rpDetail').style.display='none'">Close</button></div></div>
<div class="detail-grid">${cell('Recommended order',fmt(p.reco_qty)+' units',uc?`≈ ${fmtRpS(p.reco_qty*uc.cost)}${uc.verified?'':' (cost unverified)'}`:'no unit cost')}${cell('Order-up-to (comparison)',fmt(p.reco_order_up_to)+' units',`covers lead time + review = ${p.protection_weeks} wks`)}${cell('Order by',p.order_by?(p.order_by_is_estimate?'not before ':'')+dfmt(p.order_by):'--',p.stockout_week?`stockout week ${p.stockout_week} (${dfmt(p.stockout_date)}) − ${p.lead_time_weeks}-week lead time`:'no stockout within 12 weeks')}${cell('Inventory position',fmt(Math.round(p.inventory_position)),`stock ${fmt(d.current_stock)} + incoming ${fmt(p.inventory_position-d.current_stock)}`)}
${cell('Reorder point',fmt(Math.round(p.rop)),`lead-time demand ${fmt(Math.round(p.lt_demand))} + SS ${fmt(Math.round(p.safety_stock))}`)}${cell('Safety stock',fmt(Math.round(p.safety_stock)),'10% × 8-week forecast (policy)')}${cell('Confirmed incoming',fmt(p.confirmed_incoming),'PO with ETA')}${cell('Unconfirmed incoming',p.unconfirmed_incoming?`<span style="color:var(--amber)">${fmt(p.unconfirmed_incoming)}</span>`:'0',p.unconfirmed_incoming?`if it arrives: reco ${fmt(p.reco_if_unconfirmed_arrives)}, stockout ${p.stockout_week_if_unconfirmed_arrives?'week '+p.stockout_week_if_unconfirmed_arrives:'none'}`:'no PO without ETA')}</div>
${p.flags&&p.flags.length?`<div class="banner warn" style="margin-bottom:14px">${ICON.alert.replace('<svg','<svg class="b-ico"')}<div>${p.flags.map(f=>({negative_stock:'Book stock is negative: projection starts at 0, the deficit is included in the order.',lead_time_beyond_horizon:'Lead time is longer than the 12-week forecast horizon: demand is capped at 12 weeks.',protection_beyond_horizon:'Lead time + review period exceeds the 12-week forecast: order-up-to is capped at 12 weeks.'}[f]||f)).join('<br>')}</div></div>`:''}
<div class="section-label" style="font-size:16px;margin-bottom:8px">Weekly stock projection <span class="section-meta" style="font-size:13px">conservative: PO without ETA never arrives · forecast is an estimate</span></div>
<div class="proj-wrap"><table class="proj-table"><thead><tr><th>Week</th>${pr.map(w=>`<th title="${w.week_start||''}">W${w.week}<br><span style="font-weight:400">${(w.week_start||'').slice(5)}</span></th>`).join('')}</tr></thead><tbody>${row('Opening stock','opening')}${row('Forecast demand','demand')}${row('Incoming PO','incoming',w=>w.incoming?'inc':'')}${row('Closing stock','closing',w=>w.closing<=0&&w.demand>0?'neg':'')}${row('Unmet demand','shortage',w=>w.shortage?'neg':'')}</tbody></table></div>
<div class="two-col" style="margin-top:18px"><div><div class="section-label" style="font-size:16px;margin-bottom:8px">Open PO lines</div>${pol.length?`<div class="tbl-wrap"><table><thead><tr><th>Status</th><th class="r">Outstanding</th><th>ETA</th><th>Supplier</th></tr></thead><tbody>${pol.map(l=>`<tr><td>${poBadge(l.status||'pending')}</td><td class="r t-strong">${fmt(l.qty)}</td><td>${l.eta_source==='unknown'?'<span class="tag tag-warn">Unknown</span>':l.eta+(l.eta_source==='estimated'?' <span class="tag tag-info">est.</span>':'')+(l.overdue?' <span class="tag" style="background:var(--red-bg);color:var(--red)">overdue</span>':'')}${l.eta_week?` <span class="text-dim">(W${l.eta_week})</span>`:''}</td><td>${esc(l.supplier||'-')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state" style="padding:16px">No open PO for this SKU.</div>'}</div>
<div><div class="section-label" style="font-size:16px;margin-bottom:8px">Safety stock comparison <span class="section-meta" style="font-size:13px">simulation only</span></div><div class="tbl-wrap"><table><thead><tr><th>Scenario</th><th class="r">Safety stock</th><th class="r">Reco qty</th><th class="r">Stockout</th></tr></thead><tbody>${(sc.sensitivity||[]).map(x=>`<tr${x.is_default?' style="font-weight:700"':''}><td>${Math.round(x.ss_pct*100)}% of 8-wk forecast${x.is_default?' <span class="tag tag-info">used</span>':''}</td><td class="r">${fmt(Math.round(x.safety_stock))}</td><td class="r">${fmt(x.reco_qty)}</td><td class="r">${x.stockout_week?'W'+x.stockout_week:'> 12'}</td></tr>`).join('')}<tr><td title="${esc(sc.statistical?.method||'')}">Statistical z·σ·√L (95%)</td><td class="r">${sc.statistical?.value!=null?fmt(Math.round(sc.statistical.value)):'--'}</td><td class="r col-dim" colspan="2">not used in the recommendation</td></tr></tbody></table></div></div></div>`;
box.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){box.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}

/* ═══ DEMAND PLAN ═══ */
let planData=null,planSeq=0,dpMetric='units',dpView='plan',whyKey=null;
async function loadPlan(){const seq=++planSeq,pt=PT;if(planData&&planData._pt===pt){renderPlan();return}document.getElementById('dpTableWrap').innerHTML='<div class="loader-full"><span class="loading-spinner"></span> Loading...</div>';
try{const r=await fetch(`/api/forecast/plan?product_type=${pt}`);if(!r.ok)throw new Error('Demand plan request failed ('+r.status+')');const d=await r.json();if(seq!==planSeq)return;d._pt=pt;planData=d;buildMonths();renderPlan()}catch(e){document.getElementById('dpTableWrap').innerHTML='<div class="empty-state">'+esc(e.message)+'</div>'}}
const mkey=w=>String(w).slice(0,7);
function buildMonths(){const past=new Set(),fut=new Set();(planData.results||[]).forEach(p=>{(p.holdout.weeks||[]).forEach(w=>past.add(mkey(w)));(p.forecast.weeks||[]).forEach(w=>fut.add(mkey(w)))});
planData._months=[...[...past].sort().map(k=>({k,past:true})),...[...fut].sort().map(k=>({k,past:false}))]}
function mLabel(k){const [y,m]=k.split('-');return`${MON_S[+m-1]} ${y}`}
function monthAgg(p,mo){const price=p.avg_price;const conv=q=>dpMetric==='units'?q:(price!=null?q*price:null);
if(mo.past){const h=p.holdout;if(!h.actual||!h.forecast)return{none:true};let pl=0,ac=0,n=0;const wk=[];h.weeks.forEach((w,i)=>{if(mkey(w)===mo.k){pl+=h.forecast[i];ac+=h.actual[i];n++;wk.push(w)}});if(!n)return{empty:true};return{plan:conv(pl),act:conv(ac),n,weeks:wk}}
let pl=0,n=0;const wk=[];p.forecast.weeks.forEach((w,i)=>{if(mkey(w)===mo.k){pl+=p.forecast.quantities[i];n++;wk.push(w)}});if(!n)return{empty:true};return{plan:conv(pl),n,weeks:wk}}
function fmtV(v){return v==null?'--':(dpMetric==='units'?fmt(Math.round(v)):fmtRpS(v))}
function renderPlan(){if(!planData)return;const months=planData._months||[];const q=(document.getElementById('dpSearch').value||'').toLowerCase();let rows=planData.results||[];if(q)rows=rows.filter(p=>p.sku.toLowerCase().includes(q)||p.product_name.toLowerCase().includes(q));
if(!(planData.results||[]).length){document.getElementById('dpTableWrap').innerHTML='<div class="empty-state">No forecast yet. Upload sales data and run Refresh forecast.</div>';return}
const firstFut=months.findIndex(m=>!m.past);
let h='<table class="dp-table"><thead><tr><th rowspan="2">Product</th>'+months.map((mo,i)=>`<th class="mo ${i===firstFut?'next':''} sep" colspan="${mo.past?3:1}">${mLabel(mo.k)}${mo.past?' <span class="tag tag-info" title="Plan from a model trained without these weeks">holdout</span>':''}</th>`).join('')+'</tr><tr>'+months.map(mo=>mo.past?'<th class="sub sep">Plan</th><th class="sub">Actual</th><th class="sub">Var.</th>':'<th class="sub sep">Plan</th>').join('')+'</tr></thead><tbody>';
const tot=months.map(()=>({plan:0,act:0,ok:true}));
rows.forEach(p=>{const w=p.holdout.wmape;h+=`<tr><td class="prod"><div class="p-name" title="${esc(p.product_name)}">${esc(p.product_name)}</div><div class="p-sku">${esc(p.sku)}${w!=null?` · WMAPE ${w}%`:''}</div></td>`;
months.forEach((mo,i)=>{const a=monthAgg(p,mo);const key=p.sku+'|'+mo.k+'|'+(mo.past?'h':'f');const act=whyKey===key?'active':'';const sk=String(p.sku).replace(/'/g,"\\'");
if(a.none||a.empty){if(a.plan==null)tot[i].ok=tot[i].ok;h+=mo.past?`<td class="num sep text-dim" colspan="3" title="${a.none?'Holdout not computed yet — run Refresh forecast':''}">${a.none?'refresh':'--'}</td>`:'<td class="num sep text-dim">--</td>';return}
if(a.plan!=null)tot[i].plan+=a.plan;if(a.act!=null)tot[i].act+=a.act;
if(mo.past){const v=a.plan?(a.act-a.plan)/a.plan*100:null;const vc=v==null?'':Math.abs(v)<=10?'var(--green)':Math.abs(v)<=25?'var(--amber)':'var(--red)';h+=`<td class="num plan sep ${act}" onclick="openWhy('${sk}','${mo.k}',true)">${fmtV(a.plan)}</td><td class="num act">${fmtV(a.act)}</td><td class="num var" style="color:${vc}">${v==null?'--':(v>0?'+':'')+v.toFixed(0)+'%'}</td>`}
else h+=`<td class="num plan sep ${act}" onclick="openWhy('${sk}','${mo.k}',false)">${fmtV(a.plan)}</td>`});h+='</tr>'});
h+='<tr class="total"><td class="prod">Total · '+fmt(rows.length)+' products</td>'+months.map((mo,i)=>{const t=tot[i];if(mo.past){const v=t.plan?(t.act-t.plan)/t.plan*100:null;return`<td class="num sep">${fmtV(t.plan)}</td><td class="num">${fmtV(t.act)}</td><td class="num var">${v==null?'--':(v>0?'+':'')+v.toFixed(0)+'%'}</td>`}return`<td class="num sep">${fmtV(t.plan)}</td>`}).join('')+'</tr></tbody></table>';
if(!rows.length)h='<div class="empty-state">No products match.</div>';document.getElementById('dpTableWrap').innerHTML=h}
const WIC={hist:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><polyline points="12 7 12 12 15 14"/></svg>',par:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="4" y1="21" x2="4" y2="14"/><line x1="4" y1="10" x2="4" y2="3"/><line x1="12" y1="21" x2="12" y2="12"/><line x1="12" y1="8" x2="12" y2="3"/><line x1="20" y1="21" x2="20" y2="16"/><line x1="20" y1="12" x2="20" y2="3"/></svg>',lvl:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/></svg>',acc:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/></svg>',cmp:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M3 3v18h18"/><path d="M7 14l4-4 4 4 5-5"/></svg>'};
function openWhy(sku,mk,past){const p=(planData.results||[]).find(x=>x.sku===sku);if(!p)return;whyKey=sku+'|'+mk+'|'+(past?'h':'f');renderPlan();const a=monthAgg(p,{k:mk,past});const m=p.model,h=p.holdout;const w=document.getElementById('why');w.hidden=false;document.getElementById('dpLayout').classList.add('open');
const wk=(a.weeks||[]).map(x=>{const d=new Date(x+'T00:00:00');return`${d.getDate()} ${MON_S[d.getMonth()]}`}).join(', ');const v=past&&a.plan?(a.act-a.plan)/a.plan*100:null;
w.innerHTML=`<div class="why-h">Why this number <span>${mLabel(mk)} · ${esc(sku)}</span><button class="why-x" onclick="closeWhy()" aria-label="Close">×</button></div><div class="why-b">
<div class="why-big">${fmtV(a.plan)}<small>${dpMetric==='units'?'units · ':''}Holt's DES${past?' (holdout)':''}</small></div>
<ul class="why-list">
<li>${WIC.hist}<span>Sum of <b>${a.n} weekly forecast${a.n>1?'s':''}</b> in this month (${wk}).</span></li>
${past?`<li>${WIC.hist}<span>Model trained on <b>${h.train_weeks} weeks</b> of sales, <b>without</b> the last 8 weeks, so this month is a fair test.</span></li><li>${WIC.par}<span><b>α = ${h.alpha}, β = ${h.beta}</b> — chosen by the 81-combination grid search on the training weeks only.</span></li><li>${WIC.acc}<span>Actual <b>${fmtV(a.act)}</b> (${v==null?'--':(v>0?'+':'')+v.toFixed(0)+'%'} vs plan) · WMAPE over all 8 holdout weeks <b>${h.wmape}%</b>.</span></li>`
:`<li>${WIC.hist}<span>Model trained on <b>${m.training_weeks} weeks</b> of sales (${dfmt(m.history_start)} – ${dfmt(m.history_end)}).</span></li><li>${WIC.par}<span><b>α = ${m.alpha}, β = ${m.beta}</b> — chosen by the 81-combination grid search with the lowest MAPE.</span></li>${m.level!=null?`<li>${WIC.lvl}<span>Final level <b>${fmt(m.level)}/week</b>, trend <b>${m.trend>0?'+':''}${Number(m.trend).toFixed(1)}/week</b>. Forecast for week m = level + m × trend (never below 0).</span></li>`:''}<li>${WIC.acc}<span>Accuracy: MAPE in-sample <b>${m.mape!=null?m.mape.toFixed(1)+'%':'--'}</b> · WMAPE holdout <b>${h.wmape!=null?h.wmape+'%':'not computed'}</b>.</span></li>${p.trend_pct!=null?`<li>${WIC.cmp}<span>Next 8 weeks average is <b>${p.trend_pct>0?'+':''}${p.trend_pct}%</b> vs the last 8 weeks of actual sales${p.l4w_avg!=null?` (last 4 weeks: ${fmt(p.l4w_avg)}/week)`:''}.</span></li>`:''}`}
</ul>${dpMetric==='sales'?`<div class="why-not" style="margin-top:12px">Sales (Rp) = units × average selling price of the last 12 weeks (${p.avg_price!=null?fmtRp(p.avg_price):'n/a'}).</div>`:''}
<div class="why-not">Holt's DES models only <b>level and trend</b>. Seasonality, promotions and past stockouts are <b>not</b> taken into account — this is an estimate, not a certainty.</div></div>`;
if(innerWidth<=1100)setTimeout(()=>w.scrollIntoView({behavior:'smooth',block:'nearest'}),50)}
function closeWhy(){const w=document.getElementById('why');if(!w)return;w.hidden=true;document.getElementById('dpLayout').classList.remove('open');whyKey=null;renderPlan()}
document.querySelectorAll('#dpMetric button').forEach(b=>b.addEventListener('click',()=>{dpMetric=b.dataset.v;markSeg('dpMetric',dpMetric);if(whyKey){const [sk,mk,t]=whyKey.split('|');renderPlan();openWhy(sk,mk,t==='h')}else renderPlan()}));
document.querySelectorAll('#dpView button').forEach(b=>b.addEventListener('click',()=>{dpView=b.dataset.v;markSeg('dpView',dpView);document.getElementById('dpPlanWrap').hidden=dpView!=='plan';document.getElementById('wkWrap').hidden=dpView!=='weekly';if(dpView==='weekly')loadWeekly();else loadPlan()}));

/* ═══ SKU DRAWER (Product Analysis / PO) ═══ */
let sdChartObj=null;
function closeSkuDrawer(){document.getElementById('skuDrawer').hidden=true;if(sdChartObj){sdChartObj.destroy();sdChartObj=null}}
async function openSkuDrawer(sku){const m=document.getElementById('skuDrawer');m.hidden=false;document.getElementById('sdTitle').textContent=sku;document.getElementById('sdSub').textContent='';document.getElementById('sdBody').innerHTML='<div class="loader-full"><span class="loading-spinner"></span> Loading...</div>';
try{const r=await fetch(`/api/product/${encodeURIComponent(sku)}/history`);const d=await r.json();if(!r.ok)throw new Error(d.detail||'Not found');const inv=(invData||[]).find(x=>x.sku===sku)||{};const fc=fcDataMap[sku];
document.getElementById('sdTitle').textContent=d.product_name;document.getElementById('sdSub').innerHTML=`${esc(sku)} · ${statusBadge(inv.status)} ${inv.movement?moveBadge(inv.movement):''} ${fc?'· forecasted best seller':'· not forecasted'}`;
const cell=(l,v,sub='')=>`<div><div class="d-l">${l}</div><div class="d-v">${v}</div>${sub?`<div class="d-s">${sub}</div>`:''}</div>`;
const snaps=d.stock_snapshots||[];const pos=d.purchase_orders||[];
document.getElementById('sdBody').innerHTML=`<div class="detail-grid">${cell('Stock on hand',inv.current_stock!=null?fmt(inv.current_stock):'--',snaps.length?'snapshot '+snaps[snaps.length-1].date:'no snapshot')}${cell('Coverage',inv.coverage!=null?inv.coverage.toFixed(1)+' wks':'--',inv.days_of_inventory!=null?fmt(inv.days_of_inventory)+' days of inventory':'')}${cell('Inventory value',inv.inventory_value!=null?fmtRpS(inv.inventory_value):'No cost',inv.unit_cost?`unit cost ${fmtRp(inv.unit_cost)}${inv.cost_verified?'':' · unverified'}`:'')}${cell('Forecast / week',fc?fc.fc_avg_8w:'--',fc?trendClassBadge(fc.trend_class,fc.trend_pct):'only best sellers are forecasted')}</div>
<div class="section-label" style="font-size:16px">Sales trend <span class="section-meta" style="font-size:13px">actual units per week, last 52 weeks${fc?' · dashed = forecast':''}</span></div><div class="chart-wrap" style="height:240px"><canvas id="sdChart"></canvas></div>
<div class="two-col" style="margin-top:18px"><div><div class="section-label" style="font-size:16px;margin-bottom:8px">Stock movement</div>${snaps.length>=2?`<div class="tbl-wrap"><table><thead><tr><th>Snapshot</th><th class="r">Stock</th><th class="r">Change</th></tr></thead><tbody>${snaps.slice().reverse().map((x,i,a)=>{const prev=a[i+1];const ch=prev?x.qty-prev.qty:null;return`<tr><td>${x.date}</td><td class="r t-strong">${fmt(x.qty)}</td><td class="r ${ch>0?'num-pos':ch<0?'num-neg':''}">${ch==null?'--':(ch>0?'+':'')+fmt(ch)}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state" style="padding:16px">Stock movement needs at least 2 stock snapshots (have ${snaps.length}). Upload the stock report weekly.</div>`}</div>
<div><div class="section-label" style="font-size:16px;margin-bottom:8px">Purchase orders</div>${pos.length?`<div class="tbl-wrap"><table><thead><tr><th>Status</th><th class="r">Ordered</th><th class="r">Received</th><th>ETA</th></tr></thead><tbody>${pos.slice(0,8).map(p=>`<tr><td>${poBadge(p.status)}</td><td class="r">${fmt(p.qty_ordered)}</td><td class="r">${fmt(p.qty_received)}</td><td>${p.expected_date||'<span class="text-dim">-</span>'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state" style="padding:16px">No purchase orders for this SKU.</div>'}</div></div>`;
const ws=d.weekly_sales||[];const fw=fc?fc.forecast_data.weeks:[],fq=fc?fc.forecast_data.quantities:[];const labels=[...ws.map(w=>w.week.slice(5)),...fw.map(w=>String(w).slice(5))];const act=[...ws.map(w=>w.qty),...fw.map(()=>null)];const fcl=[...ws.map(()=>null),...fq];if(ws.length&&fq.length)fcl[ws.length-1]=ws[ws.length-1].qty;
const ctx=document.getElementById('sdChart').getContext('2d');if(sdChartObj)sdChartObj.destroy();const c1=cv('--chart-1'),c2=cv('--chart-2');sdChartObj=new Chart(ctx,{type:'line',data:{labels,datasets:[{label:'Actual',data:act,borderColor:c1,backgroundColor:areaFill(ctx,c1),fill:true,tension:.3,pointRadius:0,borderWidth:2},{label:'Forecast',data:fcl,borderColor:c2,borderDash:[6,4],fill:false,tension:.3,pointRadius:0,borderWidth:2}]},options:baseOpts(v=>fmt(v),c=>`${c.dataset.label}: ${fmt(Math.round(c.parsed.y))} units`)})}catch(e){document.getElementById('sdBody').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}

/* ═══ UPLOAD: DATA STATUS ═══ */
async function loadDataStatus(){const el=document.getElementById('dataStatus');try{const [st,inv]=await Promise.all([fetch('/api/db/stats').then(r=>r.json()),fetch(`/api/inventory/summary?product_type=all`).then(r=>r.json())]);const f=inv.freshness||{};
const lvl={fresh:['badge-green','Fresh'],stale:['badge-yellow','Stale'],very_stale:['badge-red','Very stale']}[f.stock_level]||['badge-gray','None'];
el.innerHTML=`<div><div class="s-l">Latest stock snapshot</div><div class="s-v">${f.stock_date||'--'} <span class="badge ${lvl[0]}">${lvl[1]}</span></div><div class="kpi-help">${f.stock_age_days!=null?f.stock_age_days+' days old · ':''}${inv.snapshot_count||0} snapshot(s) stored</div></div>
<div><div class="s-l">Latest sales date</div><div class="s-v">${f.last_sale_date||'--'}</div><div class="kpi-help">${f.sales_age_days!=null?f.sales_age_days+' days ago · ':''}${fmt(st.sales)} sales rows</div></div>
<div><div class="s-l">Forecast</div><div class="s-v">${fmt(st.forecast_entries)} SKUs</div><div class="kpi-help">best sellers, Pareto 80% import revenue</div></div>
<div><div class="s-l">Products</div><div class="s-v">${fmt(st.products)}</div><div class="kpi-help">${fmt(st.unique_skus)} with sales</div></div>`;
const sd=document.getElementById('stockDate');if(sd&&!sd.value){sd.value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10)}sd.max=new Date().toISOString().slice(0,10)}catch(e){el.innerHTML='<div class="empty-state">'+esc(e.message)+'</div>'}}

/* ═══ THEME: see settings section below ═══ */

/* ═══ INIT ═══ */
/* init runs at the end of the script */

/* ═══ SETTINGS / ACCOUNT ═══ */
const SKEY='po-settings-v4';
const DEFAULTS={name:'',role:'',email:'',theme:'light',period:'l4w'};
function getSettings(){try{return Object.assign({},DEFAULTS,JSON.parse(localStorage.getItem(SKEY)||'{}'))}catch(e){return Object.assign({},DEFAULTS)}}
function saveSettings(s){try{localStorage.setItem(SKEY,JSON.stringify(s))}catch(e){}}
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function resolveTheme(t){return t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t}
function rerenderCharts(){if(lastTrend){renderRevChart(lastTrend,lastAgg);renderSalesChart(lastTrend,lastAgg)}if(lastProj)renderProjChart();if(lastSku)renderSkuChart()}
function setTheme(t){const r=resolveTheme(t);if(document.documentElement.getAttribute('data-theme')!==r){document.documentElement.setAttribute('data-theme',r);rerenderCharts()}}
function toggleTheme(){const s=getSettings();s.theme=document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark';saveSettings(s);setTheme(s.theme)}
try{matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(getSettings().theme==='system')setTheme('system')})}catch(e){}
function initials(n){const p=String(n||'').trim().split(/\s+/).filter(Boolean);if(!p.length)return'?';return((p[0][0]||'')+(p.length>1?p[p.length-1][0]:'')).toUpperCase()}
function greetingWord(){const h=new Date().getHours();return h>=5&&h<12?'Good morning':h>=12&&h<17?'Good afternoon':'Good evening'}
function renderGreeting(){const s=getSettings();const g=greetingWord();document.getElementById('greeting').innerHTML=s.name?`${g}, <span class="name">${esc(s.name)}</span>`:g;const av=document.getElementById('headAvatar');av.textContent=initials(s.name);av.title=s.name?`${s.name} · Account settings`:'Account settings'}
setInterval(renderGreeting,60000);
function markSeg(id,v){document.querySelectorAll(`#${id} button`).forEach(b=>b.classList.toggle('active',b.dataset.v===v))}
function setActivePill(p){document.querySelectorAll('.pill').forEach(x=>x.classList.toggle('active',x.dataset.p===p))}
function applySettings(){const s=getSettings();currentPreset=s.period||'l4w';setActivePill(currentPreset);renderGreeting()}
let draft=null,lastFocus=null;
function openSettings(){draft=getSettings();lastFocus=document.activeElement;document.getElementById('setName').value=draft.name;document.getElementById('setRole').value=draft.role;document.getElementById('setEmail').value=draft.email;markSeg('setTheme',draft.theme);markSeg('setPeriod',draft.period);previewSettings();document.getElementById('settingsModal').hidden=false;setTimeout(()=>document.getElementById('setName').focus(),50)}
function previewSettings(){const n=document.getElementById('setName').value.trim(),r=document.getElementById('setRole').value.trim();document.getElementById('setAvatar').textContent=initials(n);document.getElementById('setPreviewName').textContent=n||'Your name';document.getElementById('setPreviewSub').textContent=r||'Set how the dashboard greets you'}
function closeSettings(){const m=document.getElementById('settingsModal');if(m.hidden)return;m.hidden=true;setTheme(getSettings().theme);if(lastFocus&&lastFocus.focus)lastFocus.focus()}
function saveSettingsForm(){const prev=getSettings();const s=Object.assign({},draft,{name:document.getElementById('setName').value.trim(),role:document.getElementById('setRole').value.trim(),email:document.getElementById('setEmail').value.trim()});saveSettings(s);closeSettings();renderGreeting();if(s.period!==prev.period){currentPreset=s.period;setActivePill(s.period);document.getElementById('dateStart').value='';document.getElementById('dateEnd').value='';loadOverview()}toast('Settings saved','success')}
document.querySelectorAll('#setTheme button').forEach(b=>b.addEventListener('click',()=>{draft.theme=b.dataset.v;markSeg('setTheme',draft.theme);setTheme(draft.theme)}));
document.querySelectorAll('#setPeriod button').forEach(b=>b.addEventListener('click',()=>{draft.period=b.dataset.v;markSeg('setPeriod',draft.period)}));

/* ═══ TOASTS ═══ */
function toast(msg,type='info'){const c={success:'var(--green)',error:'var(--red)',info:'var(--blue)'}[type]||'var(--blue)';const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="t-dot" style="background:${c}"></span><span>${esc(msg)}</span>`;document.getElementById('toasts').appendChild(el);setTimeout(()=>{el.classList.add('out');setTimeout(()=>el.remove(),220)},3600)}

/* ═══ COUNT-UP NUMBERS ═══ */
function countUp(id,target,fmtFn){const el=document.getElementById(id);if(!el)return;el.classList.remove('skel');target=Number(target)||0;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(el._raf)cancelAnimationFrame(el._raf);if(reduce){el.textContent=fmtFn(target);return}const t0=performance.now(),dur=750;const step=now=>{const t=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-t,3);el.textContent=fmtFn(t<1?Math.round(target*e):target);if(t<1)el._raf=requestAnimationFrame(step)};el._raf=requestAnimationFrame(step)}

/* ═══ INVENTORY LEGEND FILTER ═══ */
function legendFilter(st){const cur=cDropVal('invStatus');const next=cur===st?'':st;const opt=document.querySelector(`.cdrop[data-id="invStatus"] .cdrop-opt[data-val="${next}"]`);if(next&&st!=='understocked')document.getElementById('invActionOnly').checked=false;if(opt)selectCdrop(opt);document.getElementById('invTableWrap').scrollIntoView({behavior:'smooth',block:'nearest'})}

/* ═══ DRAG & DROP UPLOAD ═══ */
window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
document.querySelectorAll('.upload-card').forEach(card=>{const input=card.querySelector('input[type=file]');if(!input)return;input.addEventListener('click',()=>{input.value=''});
['dragenter','dragover'].forEach(ev=>card.addEventListener(ev,e=>{e.preventDefault();card.classList.add('drag')}));
card.addEventListener('dragleave',e=>{if(!card.contains(e.relatedTarget))card.classList.remove('drag')});
card.addEventListener('drop',e=>{e.preventDefault();card.classList.remove('drag');const f=e.dataTransfer.files[0];if(!f)return;const ok=input.accept.split(',').some(x=>f.name.toLowerCase().endsWith(x.trim()));if(!ok){toast(`${f.name} is not a supported file (${input.accept})`,'error');return}const dt=new DataTransfer();dt.items.add(f);input.files=dt.files;input.dispatchEvent(new Event('change'))})});

/* ═══ KEYBOARD SHORTCUTS ═══ */
document.addEventListener('keydown',e=>{const tag=(e.target.tagName||'').toLowerCase();const typing=(tag==='input'&&!['checkbox','radio','button','submit'].includes(e.target.type))||tag==='textarea'||tag==='select'||e.target.isContentEditable;const modalOpen=!document.getElementById('settingsModal').hidden;const loginOpen=!document.getElementById('loginOverlay').classList.contains('hidden');
if(e.key==='Escape'){if(!document.getElementById('skuDrawer').hidden){closeSkuDrawer();return}if(whyKey){closeWhy();return}if(modalOpen){closeSettings();return}closeAllCdrops();document.getElementById('customRange').classList.remove('show');document.getElementById('monthGrid').classList.remove('show');if(document.getElementById('sub-forecast').classList.contains('active'))closeSkuDetail();if(typing)e.target.blur();return}
if(typing||modalOpen||loginOpen||e.metaKey||e.ctrlKey||e.altKey)return;
const map={'1':'overview','2':'replenishment','3':'analysis','4':'po','5':'upload'};if(map[e.key]){switchTab(map[e.key]);return}
if(e.key==='/'){const sb=document.querySelector('.tab-content.active .search-box');if(sb){e.preventDefault();sb.focus()}}});

/* ═══ LOGIN / LOGOUT (server-side, see auth.py) ═══ */
const _fetch=window.fetch.bind(window);
let sessionExpiredShown=false;
window.fetch=async(input,init)=>{const r=await _fetch(input,init);const url=typeof input==='string'?input:(input&&input.url)||'';
  if(r.status===401&&url.indexOf('/api/auth/')===-1&&document.getElementById('loginOverlay').classList.contains('hidden')){if(!sessionExpiredShown){sessionExpiredShown=true;toast('Your session has ended. Please log in again.','info')}showLogin()}
  return r};
function showLogin(msg){document.getElementById('waitScreen').classList.remove('active');document.getElementById('loginOverlay').classList.remove('hidden');document.getElementById('loginStatus').textContent=msg||'';setTimeout(()=>document.getElementById('loginEmail').focus(),50)}
function togglePw(){const i=document.getElementById('loginPass');const show=i.type==='password';i.type=show?'text':'password';document.getElementById('pwEye').setAttribute('aria-label',show?'Hide password':'Show password')}
function forgotPw(){toast('Ask your system admin to reset your password.','info')}
let appStarted=false;
async function startApp(username){sessionExpiredShown=false;const s=getSettings();if(username&&!s.name){s.name=username;saveSettings(s)}applySettings();
  const ws=document.getElementById('waitScreen');ws.classList.add('active');document.getElementById('loginOverlay').classList.add('hidden');
  const t0=Date.now();
  const capped=pr=>Promise.race([pr,new Promise(r=>setTimeout(r,3000))]);
  if(!appStarted){appStarted=true;renderMonthGrid();loadPoList();await capped(loadOverview())}
  else{invSummaryCache=null;invOv=null;replData=null;planData=null;weeklyData=[];weeklyByCat={};weeklyShownCat=null;fcDataMap={};loadPoList();await capped(loadOverview());reloadActive();if(activeTab()==='po')loadPoPage();if(activeTab()==='upload')loadDataStatus()}
  setTimeout(()=>ws.classList.remove('active'),Math.max(0,600-(Date.now()-t0)))}
async function doLogin(){const btn=document.getElementById('loginBtn'),status=document.getElementById('loginStatus');
  const username=document.getElementById('loginEmail').value.trim(),password=document.getElementById('loginPass').value;
  if(!username||!password){status.textContent='Enter your username and password.';return}
  btn.disabled=true;btn.textContent='Logging in...';status.textContent='';
  try{const r=await _fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({username,password,remember:document.getElementById('loginRemember').checked})});
    const d=await r.json().catch(()=>({}));
    if(!r.ok){status.textContent=d.detail||('Login failed ('+r.status+')');document.getElementById('loginPass').select();return}
    document.getElementById('loginPass').value='';await startApp(d.username)}
  catch(e){status.textContent='Cannot reach the server. Check your connection.'}
  finally{btn.disabled=false;btn.textContent='Log In'}}
async function handleLogout(){if(!confirm('Log out?'))return;try{await _fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'})}catch(e){}showLogin()}

/* ═══ INIT ═══ */
applySettings();
(async()=>{try{const r=await _fetch('/api/auth/me',{credentials:'same-origin'});if(r.ok){const d=await r.json();await startApp(d.username);return}}catch(e){}showLogin()})();
